window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[99]={"id":"099","numero":99,"titre":"Céphalée · Migraine · AVF · Névralgies craniofaciales","objectifs":[{"id":"99-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des céphalées et douleurs de la face","contenu":"<div class=\"notion-course\"><h4>Des maladies fréquentes, avec un retentissement très variable</h4><table><thead><tr><th>Affection</th><th>Ordre de grandeur</th><th>Terrain / particularité</th></tr></thead><tbody><tr><td>Migraine</td><td>Environ 15 % des adultes ; la <span class=\"nc-red_bg\">forme chronique</span> concerne environ 1–2 %.</td><td><span class=\"nc-pink_bg\">Prédominance féminine</span> après la <span class=\"nc-pink nc-bold\">puberté</span>, environ 2 à 3 femmes pour 1 homme ; début souvent jeune. Handicap important, parfois invisible.</td></tr><tr><td>Céphalée de tension</td><td>Céphalée primaire la plus fréquente.</td><td><span class=\"nc-brown_bg\">Intensité</span> souvent moindre que la migraine ; des formes <span class=\"nc-red nc-bold\">chroniques</span> invalidantes existent.</td></tr><tr><td>Algie vasculaire de la face (AVF)</td><td>Environ 1 personne sur 1 000.</td><td>Prédominance masculine ; début habituellement chez l’adulte. Douleur <span class=\"nc-yellow_bg\">très intense</span> et retentissement psychique majeur possible.</td></tr><tr><td>Névralgie du trijumeau</td><td>Rare : environ 5–20 nouveaux cas pour 100 000 personnes/an selon les séries du collège.</td><td>Incidence augmentant avec l’âge, <span class=\"nc-pink_bg\">prédominance féminine</span> ; début souvent après <span class=\"nc-pink nc-bold\">50–60 ans</span>.</td></tr></tbody></table><ul><li>Les <span class=\"nc-blue_bg\">douleurs</span> de la face peuvent provenir d’une céphalée primaire, d’un nerf ou d’une cause locale dentaire/ORL/oculaire.</li><li>La fréquence d’une maladie ne permet pas de négliger une cause secondaire devant une douleur nouvelle ou différente.</li><li>Âge et sexe sont des arguments de terrain, <strong>pas des critères obligatoires</strong> du diagnostic.</li><li>Le retentissement s’évalue en jours douloureux, consommation de <span class=\"nc-pink\">traitements</span>, limitation des activités et qualité de vie.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181be86ade102c28b25ad?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée de tension</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e9835eec8613b4ca45?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Algie vasculaire de la face</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://campus.neurochirurgie.fr/article1715.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de neurochirurgie · Item 99, arbre décisionnel figure 7.7</a></li></ul><p>Ordres de grandeur distingués des critères diagnostiques ; incidence de la névralgie exprimée en intervalle selon les séries.</p></details>","frequence":1},{"id":"99-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les bases physiopathologiques de la migraine","contenu":"<div class=\"notion-course\"><h4>Une susceptibilité cérébrale, puis activation des voies de la douleur</h4><p>La migraine est une maladie neurologique à forte composante génétique, avec une sensibilité particulière aux variations de l’homéostasie. Elle ne se résume pas à une simple dilatation des vaisseaux.</p><table><thead><tr><th>Temps de la crise</th><th>Mécanisme</th><th>Traduction possible</th></tr></thead><tbody><tr><td>Prodromes</td><td>Modifications de réseaux hypothalamiques et de la régulation végétative.</td><td><span class=\"nc-blue_bg\">Bâillements</span>, <span class=\"nc-blue_bg\">fatigue</span>, fringales, troubles de l’humeur ou <span class=\"nc-red_bg\">hypersensibilité sensorielle</span> avant la douleur.</td></tr><tr><td>Aura, lorsqu’elle existe</td><td>Dépolarisation / <span class=\"nc-orange_bg\">dépression</span> corticale envahissante se propageant lentement dans le cortex.</td><td>Symptômes neurologiques progressivement extensifs et réversibles : <span class=\"nc-green_bg\">visuels</span>, <span class=\"nc-green_bg\">sensitifs</span>, langage.</td></tr><tr><td>Céphalée</td><td><span class=\"nc-yellow_bg\">Activation du système trigémino-vasculaire</span> et libération de neuropeptides, dont le CGRP.</td><td>Douleur avec <span class=\"nc-red_bg\">hypersensibilité sensorielle</span> ; sensibilisation périphérique et centrale possible.</td></tr><tr><td>Postdromes</td><td>Retour progressif vers l’état habituel.</td><td><span class=\"nc-blue_bg\">Fatigue</span> et difficultés de concentration après la disparition de la douleur.</td></tr></tbody></table><h4>Comprendre les symptômes et les <span class=\"nc-pink\">traitements</span></h4><ul><li>Les afférences trigéminales et cervicales convergent dans le <strong>complexe trigémino-cervical</strong> : une migraine peut être ressentie dans la face ou le cou.</li><li>La sensibilisation centrale peut produire une <strong><span class=\"nc-red_bg nc-bold\">allodynie cutanée</span></strong> : une stimulation habituellement indolore devient douloureuse.</li><li>Les triptans agissent notamment sur les récepteurs 5-HT1B/1D ; les anticorps et gépants ciblent la voie du CGRP.</li><li>L’aura n’est ni obligatoire ni assimilable à une ischémie. Une première manifestation déficitaire ou atypique impose cependant d’éliminer une cause vasculaire.</li><li>Une fringale ou une intolérance à la lumière peut être un prodrome, puis être attribuée à tort à un facteur déclenchant.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://sfemc.fr/professionnels/recommandations/migraine-treatment-position-paper-of-the-french-headache-society-article-en-anglais/\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Actualisation de la place des traitements de la migraine, position paper</a></li></ul><p>Physiopathologie réorganisée par phase, sans réduire la migraine à un mécanisme vasculaire isolé.</p></details>","frequence":0},{"id":"99-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'une céphalée primaire","contenu":"<div class=\"notion-course\"><h4>D’abord : cette douleur est-elle habituelle ?</h4><p>Demander le <strong>mode de début</strong>, la date de la première douleur et ce qui a changé. Une céphalée brutale, récente ou inhabituelle doit faire rechercher une cause secondaire, y compris chez un <span class=\"nc-brown_bg\">migraineux</span> connu.</p><table><thead><tr><th>Signal d’alerte</th><th>Conduite initiale</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Coup de tonnerre</span>, douleur maximale d’emblée</td><td>Évaluation urgente d’une cause vasculaire, notamment hémorragie sous-arachnoïdienne.</td></tr><tr><td>Déficit focal, <span class=\"nc-red nc-bold\">confusion</span>, trouble de conscience, convulsion</td><td>Filière urgente et imagerie adaptée ; ne pas conclure à une aura sans évaluation.</td></tr><tr><td>Fièvre/méningisme, immunodépression, cancer, <span class=\"nc-green_bg\">grossesse</span>/post-partum</td><td>Bilan urgent ou rapide selon le tableau.</td></tr><tr><td>Début après 50 ans, aggravation progressive, déclenchement à l’<span class=\"nc-red nc-bold\">effort</span>/Valsalva ou à la posture</td><td>Recherche d’une cause secondaire ; évoquer artérite à cellules géantes selon symptômes.</td></tr><tr><td>Œil rouge douloureux avec baisse visuelle ; Horner douloureux <span class=\"nc-red nc-bold\">récent</span></td><td>Urgence ophtalmologique ou suspicion de <span class=\"nc-orange nc-bold\">dissection carotidienne</span>.</td></tr></tbody></table><h4>Ensuite : décrire les <span class=\"nc-yellow_bg\">crises</span> avec précision</h4><ol><li>Durée <strong>sans traitement</strong>, fréquence des <span class=\"nc-yellow_bg\">crises</span> et nombre de jours de céphalée par mois.</li><li>Siège, côté, type de douleur, <span class=\"nc-brown_bg\">intensité</span> et caractère reproductible.</li><li><span class=\"nc-brown_bg\">Signes associés</span> : <span class=\"nc-blue_bg\">nausées</span>, photo/<span class=\"nc-blue_bg\">phonophobie</span>, aura, <span class=\"nc-brown_bg\">signes</span> autonomiques, symptômes locaux.</li><li>Comportement : besoin de repos immobile, <span class=\"nc-yellow_bg\">agitation</span>, peur du contact d’une <span class=\"nc-red nc-bold\">zone gâchette</span>.</li><li><span class=\"nc-pink\">Traitements</span> utilisés, jours de prise, efficacité, retentissement et comorbidités.</li></ol><table><thead><tr><th>Profil dominant</th><th>Orientation</th></tr></thead><tbody><tr><td>4–72 h, activité aggravante, <span class=\"nc-blue_bg\">nausées</span> ou photo + phonophobie</td><td>Migraine.</td></tr><tr><td>15–180 min, douleur <span class=\"nc-blue_bg\">orbitaire</span> <span class=\"nc-blue_bg\">unilatérale</span> <span class=\"nc-yellow_bg\">très intense</span>, <span class=\"nc-brown_bg\">signes</span> autonomiques / <span class=\"nc-yellow_bg\">agitation</span></td><td>AVF.</td></tr><tr><td>Fraction de seconde à 2 min, décharges dans le V, <span class=\"nc-red nc-bold\">zone gâchette</span></td><td>Névralgie du trijumeau.</td></tr><tr><td><span class=\"nc-yellow_bg\">Pression</span> <span class=\"nc-yellow_bg\">bilatérale</span>, légère/<span class=\"nc-pink_bg\">modérée</span>, sans aggravation à l’activité courante</td><td>Céphalée de tension.</td></tr></tbody></table><div class=\"callout\"><p>L’examen neurologique et local est indispensable. Un examen normal n’exclut pas toutes les causes <span class=\"nc-yellow_bg\">secondaires</span> ; un premier épisode ne suffit pas à remplir les critères d’une maladie à <span class=\"nc-yellow_bg\">crises</span> répétées.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181be86ade102c28b25ad?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée de tension</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e9835eec8613b4ca45?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Algie vasculaire de la face</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://archives.uness.fr/sites/campus-unf3s-2015/UNF3Smiroir/campus-numeriques/orl/enseignement/migraine/site/html/6.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège français d’ORL · Douleurs de la face, sémiologie (archive UNESS 2014)</a></li></ul><p>Triage des céphalées secondaires ajouté au raisonnement positif. Les durées orientent sans remplacer l’ensemble des critères.</p></details>","frequence":2},{"id":"99-4","rang":"A","rubrique":"Diagnostic positif","titre":"Conduire l'interrogatoire et réunir les arguments du diagnostic de migraine (avec ou sans aura)","contenu":"<div class=\"notion-course\"><h4><span class=\"nc-green_bg\">Migraine sans aura</span> : les critères à réunir</h4><ol><li><strong>Au moins 5 <span class=\"nc-yellow_bg\">crises</span></strong>.</li><li>Durée de <strong>4 à 72 heures</strong> sans traitement <span class=\"nc-red nc-bold\">efficace</span> chez l’adulte.</li><li>Au moins <strong>2</strong> caractères : <span class=\"nc-yellow_bg\">unilatérale</span>, <span class=\"nc-yellow_bg\">pulsatile</span>, <span class=\"nc-pink_bg\">modérée</span>/sévère, aggravée par les activités physiques courantes ou entraînant leur évitement.</li><li>Pendant la céphalée : <strong><span class=\"nc-blue_bg\">nausées</span>/<span class=\"nc-blue_bg\">vomissements</span></strong> ou association <strong><span class=\"nc-blue_bg\">photophobie</span> et <span class=\"nc-blue_bg\">phonophobie</span></strong>.</li><li>Absence d’une meilleure explication diagnostique.</li></ol><p>Le patient recherche souvent le <span class=\"nc-green_bg\">repos dans l’obscurité</span>. Une migraine peut être <span class=\"nc-red nc-bold\">bilatérale</span>, faciale ou cervicale ; tous les caractères ne sont pas obligatoires. Chez l’<span class=\"nc-red_bg\">enfant</span>, les <span class=\"nc-yellow_bg\">crises</span> peuvent durer <strong>2 à 72 heures</strong> et sont plus souvent bilatérales.</p><h4>Migraine avec aura : reconnaître la dynamique</h4><p>Au moins <strong>2 <span class=\"nc-yellow_bg\">crises</span></strong> avec symptômes neurologiques entièrement réversibles et au moins <strong>3 des 6</strong> caractéristiques suivantes :</p><ul><li>Un symptôme s’étend progressivement sur au moins 5 minutes.</li><li>Plusieurs symptômes apparaissent successivement.</li><li>Chaque symptôme dure habituellement <span class=\"nc-pink nc-bold\">5–60 minutes</span>.</li><li>Au moins un symptôme est <span class=\"nc-yellow_bg\">unilatéral</span>.</li><li>Au moins un symptôme est <span class=\"nc-yellow_bg\">positif</span> : scintillements, paresthésies…</li><li>La céphalée <span class=\"nc-pink_bg\">accompagne l’aura</span> ou débute dans les 60 minutes qui la suivent.</li></ul><table><thead><tr><th>Aura typique</th><th>Points de vigilance</th></tr></thead><tbody><tr><td>Visuelle</td><td><span class=\"nc-blue_bg\">Scotome scintillant</span>, <span class=\"nc-blue_bg\">zigzags</span>, perturbation d’un hémichamp ; souvent perçue dans les deux yeux. Une perte visuelle réellement monoculaire doit être explorée.</td></tr><tr><td>Sensitive</td><td>Paresthésies qui progressent, par exemple main puis bras puis face, parfois suivies d’<span class=\"nc-orange_bg\">hypoesthésie</span>.</td></tr><tr><td>Langage</td><td>Trouble réversible de la parole ou du langage, dans une séquence compatible.</td></tr></tbody></table><ul><li>L’aura typique est visuelle, sensitive et/ou du langage, <strong>sans déficit <span class=\"nc-red nc-bold\">moteur</span>, <span class=\"nc-red nc-bold\">rétinien</span> ni signe du tronc cérébral</strong>.</li><li>Une aura peut survenir sans céphalée. Chaque symptôme dure habituellement <span class=\"nc-pink nc-bold\">5–60 minutes</span> : la durée totale peut dépasser une heure si plusieurs symptômes se succèdent.</li><li>Un symptôme <span class=\"nc-red nc-bold\">moteur</span>, une atteinte monoculaire, une aura nouvelle/prolongée ou un début <span class=\"nc-red nc-bold\">brutal</span> nécessitent une évaluation spécifique ; déficit en cours : filière urgente.</li><li>Migraine <span class=\"nc-red nc-bold\">hémiplégique</span> et migraine avec <span class=\"nc-red_bg\">aura du tronc cérébral</span> existent, mais leur diagnostic est spécialisé après exclusion des causes dangereuses.</li></ul><div class=\"callout\"><p>AIT : déficit souvent <span class=\"nc-red nc-bold\">brutal</span> et maximal d’emblée. Aura : progression et succession fréquentes. Cette opposition aide à raisonner, mais ne permet pas de différer un bilan vasculaire si le tableau est inhabituel.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://ichd-3.org/1-migraine/1-2-migraine-with-aura/\" target=\"_blank\" rel=\"noopener noreferrer\">International Headache Society · ICHD-3 — Migraine avec aura</a></li></ul><p>Critères de migraine avec aura séparés de ceux de l’aura typique ; correction de l’ambiguïté « 60 minutes » pour plusieurs symptômes successifs.</p></details>","frequence":4},{"id":"99-5","rang":"A","rubrique":"Diagnostic positif","titre":"Conduire l'interrogatoire et réunir les arguments du diagnostic d'algie vasculaire de la face","contenu":"<div class=\"notion-course\"><h4>Algie vasculaire de la face : le profil caractéristique</h4><table><thead><tr><th>Critère</th><th>À rechercher</th></tr></thead><tbody><tr><td>Répétition</td><td>Au moins 5 crises pour les critères formels.</td></tr><tr><td>Douleur</td><td>Strictement <span class=\"nc-blue_bg\">unilatérale</span> pendant la crise, <span class=\"nc-blue_bg\">orbitaire</span>/<span class=\"nc-blue_bg\">sus-orbitaire</span>/temporale, <span class=\"nc-red_bg\">sévère à très sévère</span>.</td></tr><tr><td>Durée</td><td>15–180 minutes sans traitement ; une crise tous les 2 jours à 8 crises par jour en période active.</td></tr><tr><td><span class=\"nc-brown_bg\">Signes</span> associés</td><td>Au moins un signe autonomique du même côté et/ou <span class=\"nc-yellow_bg\">agitation</span>/impatience.</td></tr><tr><td>Exclusion</td><td>Pas de meilleure explication, notamment lésion secondaire.</td></tr></tbody></table><ul><li><strong><span class=\"nc-brown_bg\">Signes</span> autonomiques ipsilatéraux</strong> : <span class=\"nc-orange_bg\">larmoiement</span>/<span class=\"nc-orange_bg\">injection conjonctivale</span>, <span class=\"nc-orange_bg\">rhinorrhée</span>/congestion nasale, œdème palpébral, sueur faciale, myosis/ptosis.</li><li>Le patient est souvent <strong>agité</strong> ; il ne reste pas couché immobile comme beaucoup de <span class=\"nc-brown_bg\">migraineux</span>.</li><li>Crises volontiers à horaires fixes, parfois nocturnes, regroupées en périodes. L’<span class=\"nc-red nc-bold\">alcool</span> peut déclencher une crise durant une période active.</li><li><span class=\"nc-blue_bg\">Nausées</span> et photo/<span class=\"nc-blue_bg\">phonophobie</span> peuvent exister : elles n’éliminent pas l’AVF.</li></ul><h4>Forme épisodique ou chronique ?</h4><table><thead><tr><th>Évolution</th><th>Repère ICHD-3</th></tr></thead><tbody><tr><td>Épisodique</td><td>Périodes de crises séparées de rémissions d’au moins 3 mois.</td></tr><tr><td>Chronique</td><td>Crises depuis au moins 1 an sans rémission, ou avec des rémissions de moins de 3 mois.</td></tr></tbody></table><h4>Bilan et sécurité</h4><ul><li><span class=\"nc-blue_bg\">IRM cérébrale</span> avec étude adaptée, notamment région hypothalamo-hypophysaire et trajet vasculaire selon le tableau.</li><li>Un <strong>Horner douloureux récent</strong>, surtout avec cervicalgie ou douleur inhabituelle persistante, fait rechercher une <span class=\"nc-orange nc-bold\">dissection carotidienne</span> sans attendre.</li><li>Évaluer retentissement psychique et idées suicidaires si souffrance majeure. Une menace suicidaire relève d’une prise en charge urgente.</li><li>Le côté peut changer entre périodes ; le caractère unilatéral de la crise reste central.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181e9835eec8613b4ca45?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Algie vasculaire de la face</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://ichd-3.org/3-trigeminal-autonomic-cephalalgias/3-1-cluster-headache/3-1-2-chronic-cluster-headache/\" target=\"_blank\" rel=\"noopener noreferrer\">International Headache Society · ICHD-3 — Algie vasculaire de la face chronique</a></li></ul><p>Correction de la définition de l’AVF chronique : au moins 1 an, et non seulement 3 mois ; rémission épisodique d’au moins 3 mois.</p></details>","frequence":4},{"id":"99-6","rang":"A","rubrique":"Diagnostic positif","titre":"Conduire l'interrogatoire et réunir les arguments du diagnostic de névralgie du trijumeau","contenu":"<div class=\"notion-course\"><h4>Névralgie du trijumeau : des décharges provoquées</h4><ul><li><strong>Douleur unilatérale</strong>, dans une ou plusieurs branches du V, souvent V2 ou V3, sans irradiation habituelle hors de ce territoire.</li><li>Paroxysmes très brefs, de la fraction de seconde à environ <strong>2 minutes</strong>, à type de décharge électrique, coup de poignard ou éclair.</li><li>Déclenchement par un stimulus normalement indolore : effleurement d’une <strong><span class=\"nc-red nc-bold\">zone gâchette</span></strong>, <span class=\"nc-red nc-bold\">parole</span>, <span class=\"nc-red nc-bold\">mastication</span>, brossage des dents.</li><li>Une période réfractaire peut suivre l’accès ; le patient évite de bouger ou de manger par crainte de déclencher la douleur.</li><li>L’examen est souvent normal dans une forme classique ; tester la sensibilité faciale, le réflexe cornéen, la force masticatrice et les autres nerfs crâniens.</li></ul><table><thead><tr><th>Forme</th><th>Définition / bilan</th></tr></thead><tbody><tr><td>Classique</td><td>Conflit neurovasculaire avec compression et modifications morphologiques du nerf ; un simple contact vasculaire n’est pas une preuve suffisante.</td></tr><tr><td>Secondaire</td><td>Cause sous-jacente, notamment SEP, tumeur de l’angle pontocérébelleux/base du crâne ou autre <span class=\"nc-red nc-bold\">lésion</span>.</td></tr><tr><td>Idiopathique</td><td>Pas de cause établie après bilan approprié.</td></tr></tbody></table><h4>Quand renforcer la recherche d’une cause secondaire ?</h4><ul><li>Sujet <span class=\"nc-pink nc-bold\">jeune</span>, atteinte bilatérale, hypoesthésie persistante, abolition du réflexe cornéen, déficit moteur ou autre anomalie neurologique.</li><li>Une douleur continue associée peut exister dans une névralgie ; elle demande une analyse attentive et ne suffit pas à affirmer une <span class=\"nc-red nc-bold\">lésion</span> secondaire.</li><li>Une douleur surtout continue, brûlante, avec déficit sensitif/allodynie diffuse évoque davantage une <strong>neuropathie trigéminale douloureuse</strong>.</li><li><strong><span class=\"nc-yellow_bg\">IRM cérébrale</span> et du trajet du V</strong> avec séquences adaptées pour rechercher cause secondaire et conflit ; pas de PL <span class=\"nc-red nc-bold\">systématique</span>.</li></ul><details><summary>Autres névralgies</summary><ul><li>Glossopharyngien (IX) : douleur de la gorge/base de langue irradiant à l’oreille, déclenchée par la <span class=\"nc-red nc-bold\">déglutition</span> ; écarter notamment une tumeur ORL.</li><li>Grand occipital (Arnold, C2) : décharges occipitales vers le vertex ; ne pas attribuer toutes les migraines postérieures à ce nerf.</li></ul></details><div class=\"callout\"><p>« Femme de 60 ans avec douleur V2 » décrit un terrain fréquent, pas des critères obligatoires. La réponse à la <span class=\"nc-pink_bg\">carbamazépine</span> ne remplace pas le bilan étiologique.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://campus.neurochirurgie.fr/article1715.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de neurochirurgie · Item 99, arbre décisionnel figure 7.7</a></li></ul><p>Bilan IRM privilégié selon le CEN ; sexe, âge et réponse au médicament ne sont plus des critères diagnostiques obligatoires.</p></details>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/trigeminal-neuralgia","label":"Radiopaedia : Trigeminal neuralgia"},{"href":"https://radiopaedia.org/articles/trigeminal-nerve","label":"Radiopaedia : Trigeminal nerve (anatomie)"}]},{"id":"99-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l'intrication migraines, céphalées de tension","contenu":"<div class=\"notion-course\"><h4><span class=\"nc-red\">Migraine</span> et <span class=\"nc-red\">céphalée de tension</span> peuvent coexister</h4><table><thead><tr><th>Repère</th><th><span class=\"nc-red\">Migraine</span></th><th><span class=\"nc-red\">Céphalée de tension</span> <span class=\"nc-green_bg\">épisodique</span></th></tr></thead><tbody><tr><td>Douleur</td><td>Souvent <span class=\"nc-yellow_bg\">pulsatile</span>, <span class=\"nc-pink_bg\">modérée</span> à sévère.</td><td><span class=\"nc-yellow_bg\">Pression</span>/serrement, légère à <span class=\"nc-pink_bg\">modérée</span>, souvent <span class=\"nc-yellow_bg\">bilatérale</span>.</td></tr><tr><td>Activité courante</td><td>Aggrave ou conduit à l’éviter.</td><td>Ne l’aggrave habituellement pas.</td></tr><tr><td><span class=\"nc-brown_bg\">Signes associés</span></td><td><span class=\"nc-blue_bg\">Nausées</span>/<span class=\"nc-blue_bg\">vomissements</span> ou photo + <span class=\"nc-blue_bg\">phonophobie</span>.</td><td>Pas de <span class=\"nc-blue_bg\">nausée</span>/vomissement ; au plus l’un des deux : <span class=\"nc-blue_bg\">photophobie</span> ou <span class=\"nc-blue_bg\">phonophobie</span>.</td></tr><tr><td>Durée</td><td>4–72 h chez l’adulte.</td><td>30 minutes à 7 jours.</td></tr></tbody></table><h4>Ne pas confondre <span class=\"nc-red_bg\">chronique</span> et tension</h4><p>La <strong><span class=\"nc-red_bg\">migraine chronique</span></strong> associe des céphalées ≥ 15 jours/mois depuis plus de 3 mois, dont au moins <strong><span class=\"nc-pink nc-bold\">8 jours/mois</span></strong> avec caractéristiques migraineuses ou réponse à un traitement spécifique, chez un patient ayant un antécédent migraineux compatible.</p><ul><li>Les autres jours peuvent ressembler à des céphalées de tension. Cela ne retire pas le diagnostic de <span class=\"nc-red\">migraine</span> <span class=\"nc-red_bg\">chronique</span>.</li><li>Une <span class=\"nc-red\">céphalée de tension</span> <span class=\"nc-red_bg\">chronique</span> existe aussi ; elle ne se diagnostique pas uniquement sur le caractère quotidien de la douleur.</li><li>Un <span class=\"nc-orange_bg nc-bold\">abus médicamenteux</span> peut coexister avec la <span class=\"nc-red\">migraine</span> <span class=\"nc-red_bg\">chronique</span> : les deux diagnostics peuvent être portés.</li><li>L’<span class=\"nc-blue nc-bold\">agenda</span> distingue les jours, les différents phénotypes et les <span class=\"nc-pink\">traitements</span> pris ; il est plus fiable que « j’ai toujours mal ».</li></ul><div class=\"callout\"><p>Une <span class=\"nc-red nc-bold\">céphalée</span> quotidienne récente, une modification du profil ou un drapeau rouge impose de réexaminer les causes secondaires avant de conclure à une chronicisation.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181be86ade102c28b25ad?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée de tension</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418171be27eec2430b18ac?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée chronique quotidienne</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li></ul><p>Distinction entre coexistence de céphalées de tension et jours de douleur tensive dans une migraine chronique ; suppression de l’équivalence automatique « quotidien = migraine ».</p></details>","frequence":0},{"id":"99-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales causes de douleur de la face","contenu":"<div class=\"notion-course\"><h4>Classer la douleur faciale par mécanisme et par organe</h4><table><thead><tr><th>Groupe</th><th>Indices</th><th>Première orientation</th></tr></thead><tbody><tr><td>Céphalée primaire</td><td>Crises stéréotypées de migraine ou AVF, critères cliniques concordants.</td><td>Interrogatoire chronologique, examen neurologique et recherche d’alertes.</td></tr><tr><td>Dentaire / gingival / muqueux</td><td>Douleur thermique, à la mastication, <span class=\"nc-red nc-bold\">lésion</span> dentaire, ulcération, tuméfaction.</td><td>Examen buccodentaire et avis dentaire/ORL/CMF ciblé.</td></tr><tr><td>Sinusien / auriculaire</td><td>Rhinorrhée/obstruction, otorrhée, anomalie à l’otoscopie.</td><td>Examen ORL ; la localisation seule ne prouve pas l’origine.</td></tr><tr><td>Salivaire</td><td>Gonflement et douleur rythmés par les repas, parfois écoulement purulent.</td><td>Palpation glandulaire et examen des ostiums ; échographie selon suspicion.</td></tr><tr><td>Osseux / tumoral</td><td>Traumatisme, douleur progressive, masse, hypoesthésie du menton ; irradiation ou anti-résorptif dans les antécédents.</td><td>Imagerie et avis spécialisé ; rechercher infection, ostéonécrose ou tumeur.</td></tr><tr><td>Appareil manducateur</td><td>Douleur prétragienne/masticatrice, <span class=\"nc-green nc-bold\">claquements</span>, limitation ou blocage de l’ouverture.</td><td>Palpation <span class=\"nc-blue_bg\">ATM</span> et muscles, examen de l’occlusion ; bilan ciblé.</td></tr><tr><td>Neuropathique / névralgique</td><td>Décharges territoriales ou brûlure avec trouble sensitif.</td><td>Examen des nerfs crâniens et bilan étiologique.</td></tr><tr><td>Idiopathique persistante</td><td>Douleur chronique sans cause démontrée après bilan adapté.</td><td>Éviter gestes dentaires répétés sans cible ; prise en charge de la douleur et du retentissement.</td></tr></tbody></table><h4>Les causes graves à ne pas manquer</h4><ul><li><strong>Dissection carotidienne</strong> : douleur unilatérale récente, cervicalgie et/ou syndrome de Claude Bernard-Horner, même sans déficit.</li><li><strong>Artérite à cellules géantes</strong> : après 50 ans, claudication de la mâchoire, douleur temporale, symptômes visuels ; risque de cécité.</li><li><strong>Urgence orbitaire/oculaire</strong> : œil rouge douloureux, baisse de vision, exophtalmie ou limitation oculomotrice.</li><li><strong>Infection profonde / tumeur</strong> : fièvre, <span class=\"nc-blue_bg\">trismus</span>, dysphagie, masse, ulcération persistante ou déficit sensitif.</li><li>Une douleur faciale récente sévère sans cause locale évidente s’explore comme une céphalée secondaire.</li></ul><details><summary>Douleurs idiopathiques et stomatodynie</summary><p>Une brûlure buccale chronique sans <span class=\"nc-red nc-bold\">lésion</span> visible peut relever d’une stomatodynie après exclusion de <span class=\"nc-purple_bg\">candidose</span>, xérostomie, carence ou autre cause. L’absence de <span class=\"nc-red nc-bold\">lésion</span> ne signifie ni absence de douleur ni preuve d’une origine psychiatrique.</p></details></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181618a14ff6dc5208158?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941810c957cf9ddacfd659b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://archives.uness.fr/sites/campus-unf3s-2015/UNF3Smiroir/campus-numeriques/orl/enseignement/migraine/site/html/6.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège français d’ORL · Douleurs de la face, sémiologie (archive UNESS 2014)</a></li></ul><p>Orientation étendue aux causes salivaires, osseuses et manducatrices ; signaux vasculaires et tumoraux explicités.</p></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/occipital-neuralgia","label":"Radiopaedia : Occipital neuralgia (Arnold)"},{"href":"https://radiopaedia.org/articles/temporomandibular-joint-1","label":"Radiopaedia : Temporomandibular joint"}]},{"id":"99-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la description clinique des algies d'origine dentaire, sinusienne et buccale","contenu":"<div class=\"notion-course\"><h4>La douleur doit correspondre à des signes locaux</h4><table><thead><tr><th>Origine</th><th>Profil clinique</th><th>Examen / piège</th></tr></thead><tbody><tr><td><span class=\"nc-yellow_bg\">Pulpite</span> dentaire</td><td>Douleur intense, <span class=\"nc-red nc-bold\">spontanée</span> ou déclenchée par <span class=\"nc-red nc-bold\">chaud</span>/<span class=\"nc-red nc-bold\">froid</span> ; <span class=\"nc-yellow_bg\">parfois</span> mal localisée et irradiée.</td><td>Rechercher <span class=\"nc-red nc-bold\">carie</span>/restauration, <span class=\"nc-green_bg nc-bold\">vitalité</span> <span class=\"nc-green_bg nc-bold\">pulpaire</span> ; avis dentaire. La douleur projetée peut être prise pour une algie faciale.</td></tr><tr><td>Atteinte périapicale / abcès</td><td>Douleur à la <span class=\"nc-red_bg\">mastication</span> ou à la <span class=\"nc-red nc-bold\">percussion</span> d’une dent, <span class=\"nc-yellow_bg\">parfois</span> tuméfaction et <span class=\"nc-blue_bg nc-bold\">fièvre</span>.</td><td>Inspection, <span class=\"nc-red nc-bold\">percussion</span> douce et examen gingival. Une <span class=\"nc-red nc-bold\">cellulite</span> peut diffuser au plancher buccal et au cou.</td></tr><tr><td><span class=\"nc-red nc-bold\">Sinusite</span> <span class=\"nc-blue nc-bold\">maxillaire</span></td><td>Douleur <span class=\"nc-red nc-bold\">sous</span>-<span class=\"nc-red nc-bold\">orbitaire</span> avec obstruction et/ou <span class=\"nc-red nc-bold\">rhinorrhée</span> <span class=\"nc-red nc-bold\">purulente</span> ; <span class=\"nc-yellow_bg\">parfois</span> majorée en antéflexion.</td><td>Chercher signes nasaux et dentaires. Unilatéralité, mauvaise odeur et foyer dentaire orientent vers une origine odontogène.</td></tr><tr><td>Autres sinus</td><td><span class=\"nc-orange nc-bold\">Frontale</span> : <span class=\"nc-yellow_bg\">sus-orbitaire</span> ; <span class=\"nc-purple_bg\">sphénoïdale</span> : douleur profonde, rétro-<span class=\"nc-red nc-bold\">orbitaire</span>/<span class=\"nc-yellow_bg\">vertex</span>, <span class=\"nc-yellow_bg\">parfois</span> sans <span class=\"nc-red nc-bold\">rhinorrhée</span> ; ethmoïdale : douleur et signes péri-orbitaires.</td><td>La topographie seule ne suffit pas. Signes orbitaires ou neurologiques : rechercher une <span class=\"nc-red nc-bold\">complication</span> en urgence.</td></tr><tr><td>Muqueuse buccale</td><td>Douleur au contact d’un aphte, ulcération, <span class=\"nc-purple_bg\">candidose</span>, gingivite ou autre lésion.</td><td>Inspecter <span class=\"nc-blue nc-bold\">langue</span>, plancher, palais, <span class=\"nc-blue nc-bold\">gencives</span> et oropharynx ; palper et rechercher adénopathie.</td></tr><tr><td>Glande salivaire</td><td>Douleur et gonflement, notamment pendant les repas ; pus possible à l’ostium.</td><td>Évoquer obstacle/lithiase ou infection ; échographie et avis selon tableau.</td></tr></tbody></table><h4>Les signaux qui changent le délai</h4><ul><li><strong><span class=\"nc-blue_bg\">Trismus</span>, dysphagie, voix modifiée, tuméfaction du plancher ou gêne respiratoire</strong> : urgence pour infection profonde et menace des voies aériennes.</li><li>Œdème <span class=\"nc-red nc-bold\">orbitaire</span>, <span class=\"nc-red nc-bold\">exophtalmie</span>, <span class=\"nc-red nc-bold\">diplopie</span>, baisse visuelle ou <span class=\"nc-red nc-bold\">syndrome méningé</span> : <span class=\"nc-red nc-bold\">complication</span> sinusienne à explorer en urgence.</li><li>Ulcération persistante, induration, saignement inhabituel, masse ou adénopathie : avis spécialisé pour exclure un cancer.</li><li>Une douleur isolée de la joue ou du front sans syndrome nasal n’autorise pas à conclure à une <span class=\"nc-red nc-bold\">sinusite</span>.</li><li>Sans lésion, réévaluer névralgie, migraine, douleur idiopathique ou stomatodynie ; pas de geste dentaire irréversible sans cible.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181618a14ff6dc5208158?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941810c957cf9ddacfd659b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d94181c3bc55ca60e73b9ec9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sinusites aiguës</a></li><li><a href=\"https://archives.uness.fr/sites/campus-unf3s-2015/UNF3Smiroir/campus-numeriques/orl/enseignement/migraine/site/html/6.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège français d’ORL · Douleurs de la face, sémiologie (archive UNESS 2014)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li></ul><p>Sémiologie complétée à partir des chapitres ORL personnels, avec distinction douleur locale / douleur projetée et complications.</p></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/impacted-teeth","label":"Radiopaedia : Impacted teeth"},{"href":"https://radiopaedia.org/articles/mandibular-osteoradionecrosis","label":"Radiopaedia : Mandibular osteoradionecrosis"}]},{"id":"99-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la description clinique des céphalées d'origine auriculaire","contenu":"<div class=\"notion-course\"><h4>Otalgie : inspecter l’<span class=\"nc-brown_bg\">oreille</span>, puis chercher une douleur projetée</h4><p>Une otalgie est une douleur ressentie dans l’<span class=\"nc-brown_bg\">oreille</span>. Elle peut provenir de l’<span class=\"nc-brown_bg\">oreille</span> externe/moyenne ou d’une structure à distance ; une affection de l’<span class=\"nc-brown_bg\">oreille</span> interne donne habituellement vertige ou trouble auditif plutôt qu’une douleur isolée.</p><table><thead><tr><th>Tableau</th><th>Indices utiles</th><th>Conduite</th></tr></thead><tbody><tr><td><span class=\"nc-yellow_bg\">Otite externe</span></td><td>Douleur à la pression du tragus et à la <span class=\"nc-red nc-bold\">traction du pavillon</span> ; conduit <span class=\"nc-blue nc-bold\">inflammatoire</span>/<span class=\"nc-blue nc-bold\">œdématié</span>, otorrhée.</td><td>Otoscopie prudente ; préciser <span class=\"nc-blue_bg\">tympan</span>, terrain et extension. Une fièvre ou atteinte générale fait rechercher une complication.</td></tr><tr><td><span class=\"nc-purple_bg\">Otite moyenne aiguë</span></td><td><span class=\"nc-yellow_bg nc-bold\">Otalgie</span>, parfois fièvre/<span class=\"nc-blue_bg\">hypoacousie</span> ; <span class=\"nc-blue_bg\">tympan</span> <span class=\"nc-blue nc-bold\">inflammatoire</span> et bombant ou otorrhée après perforation.</td><td>Diagnostic otoscopique ; l’érythème isolé du <span class=\"nc-blue_bg\">tympan</span> ne suffit pas.</td></tr><tr><td>Zona auriculaire</td><td><span class=\"nc-yellow_bg nc-bold\">Otalgie</span> avec vésicules de la conque/conduit ; parfois paralysie faciale, vertige ou baisse auditive.</td><td>Examen des nerfs crâniens et avis rapide.</td></tr><tr><td><span class=\"nc-purple_bg\">Mastoïdite</span> / atteinte invasive</td><td>Douleur et tuméfaction rétro-auriculaire ; ou douleur profonde persistante chez diabétique/<span class=\"nc-orange nc-bold\">immunodéprimé</span>.</td><td>Avis ORL urgent, imagerie adaptée ; penser otite externe nécrosante si douleur disproportionnée/persistante.</td></tr><tr><td>Otalgie réflexe, otoscopie normale</td><td>Dent, <span class=\"nc-blue_bg\">ATM</span>, amygdale, pharynx/larynx ; douleur lors de <span class=\"nc-red_bg\">mastication</span> ou déglutition.</td><td>Examiner bouche, dents, <span class=\"nc-blue_bg\">ATM</span>, pharynx, cou ; nasofibroscopie par ORL si nécessaire.</td></tr></tbody></table><div class=\"callout\"><p>Une <strong>otalgie unilatérale persistante avec otoscopie normale</strong> doit faire rechercher une lésion des voies aérodigestives supérieures, surtout avec tabac/alcool, dysphagie, dysphonie, amaigrissement ou adénopathie. Ne pas multiplier les gouttes auriculaires sans diagnostic.</p></div><ul><li>Tester audition, équilibre et motricité faciale si symptômes associés.</li><li>Décharges pharyngées irradiant dans l’<span class=\"nc-brown_bg\">oreille</span>, déclenchées par déglutition : évoquer névralgie du IX après exclusion d’une cause ORL.</li><li>Une céphalée <span class=\"nc-red nc-bold\">intense</span> nouvelle associée à fièvre ou signe neurologique ne se réduit pas à une otite banale.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181618a14ff6dc5208158?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941810c957cf9ddacfd659b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941816fa676c25ddeb451ea?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Otite externe aiguë, Otalgies</a></li><li><a href=\"https://archives.uness.fr/sites/campus-unf3s-2015/UNF3Smiroir/campus-numeriques/orl/enseignement/migraine/site/html/6.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège français d’ORL · Douleurs de la face, sémiologie (archive UNESS 2014)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li></ul><p>Contenu otologique développé avec le cours personnel « Otite externe aiguë, Otalgies » ; absence de fièvre non présentée comme un critère obligatoire.</p></details>","frequence":0},{"id":"99-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention devant une douleur de la face","contenu":"<div class=\"notion-course\"><h4>L’examen clinique choisit l’examen complémentaire</h4><ol><li>Examiner neurologie et nerfs crâniens, œil/vision, bouche/dents, fosses nasales, oreilles, ATM, glandes salivaires et cou.</li><li>Préciser <span class=\"nc-pink nc-bold\">urgence</span>, organe suspecté et question posée à l’examen.</li><li>Ne pas attribuer la douleur à une anomalie fortuite sans concordance clinique.</li></ol><table><thead><tr><th>Hypothèse</th><th>Première exploration utile</th></tr></thead><tbody><tr><td><span class=\"nc-green_bg\">Migraine sans aura</span> ancienne, typique, examen normal</td><td>Pas d’imagerie <span class=\"nc-red nc-bold\">systématique</span>. Devant aura, le CEN propose une <span class=\"nc-blue_bg\">IRM</span> au moins une fois ; nouveauté/atypie ou drapeau rouge impose un bilan adapté au délai.</td></tr><tr><td>AVF / névralgie du trijumeau</td><td>IRM cérébrale avec séquences ciblées : régions pertinentes et trajet du V, recherche d’une <span class=\"nc-red nc-bold\">lésion</span> et d’un conflit.</td></tr><tr><td><span class=\"nc-pink nc-bold\">Urgence</span> vasculaire / neurologique</td><td>Imagerie cérébrale et vasculaire selon hypothèse et disponibilité ; autres examens, dont PL, sur indication. Une IRM programmée ne remplace pas la filière urgente.</td></tr><tr><td><span class=\"nc-yellow_bg\">Cause dentaire</span></td><td>Examen dentaire puis clichés rétroalvéolaires/panoramique selon le foyer suspecté.</td></tr><tr><td><span class=\"nc-red nc-bold\">Sinusite</span> aiguë <span class=\"nc-blue nc-bold\">maxillaire</span> simple</td><td>Diagnostic clinique ; pas de radiographie des sinus <span class=\"nc-red nc-bold\">systématique</span>. TDM si <span class=\"nc-red nc-bold\">complication</span>, tableau atypique, localisation à risque ou bilan spécialisé.</td></tr><tr><td>Douleur ORL persistante / otalgie réflexe</td><td>Examen ORL avec <span class=\"nc-blue_bg\">endoscopie</span> selon siège ; TDM/IRM et biopsie si <span class=\"nc-red nc-bold\">lésion</span> suspecte.</td></tr><tr><td>Obstacle salivaire</td><td>Échographie souvent première intention ; imagerie complémentaire selon la cause.</td></tr><tr><td>Artérite à cellules géantes</td><td>CRP/VS, NFS et filière spécialisée pour échographie/biopsie selon organisation. Symptômes <span class=\"nc-green_bg\">visuels</span> : traitement urgent, sans attendre la preuve histologique.</td></tr></tbody></table><p>Une radiographie anormale, un épaississement muqueux sinusien ou un simple contact vasculaire sur le V peut être fortuit. Le résultat doit expliquer le côté, la chronologie et la sémiologie.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d94181618a14ff6dc5208158?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941810c957cf9ddacfd659b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Douleurs faciales (99)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e9835eec8613b4ca45?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Algie vasculaire de la face</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d94181c3bc55ca60e73b9ec9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Sinusites aiguës</a></li><li><a href=\"https://app.notion.com/p/1cb37f85d941816fa676c25ddeb451ea?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Otite externe aiguë, Otalgies</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://archives.uness.fr/sites/campus-unf3s-2015/UNF3Smiroir/campus-numeriques/orl/enseignement/migraine/site/html/6.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège français d’ORL · Douleurs de la face, sémiologie (archive UNESS 2014)</a></li><li><a href=\"https://campus.neurochirurgie.fr/article1715.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de neurochirurgie · Item 99, arbre décisionnel figure 7.7</a></li></ul><p>Bilan ordonné par hypothèse ; pas de batterie identique pour toute douleur faciale.</p></details>","frequence":0},{"id":"99-12","rang":"A","rubrique":"Étiologies","titre":"Identifier les facteurs favorisants éventuels d'une migraine","contenu":"<div class=\"notion-course\"><h4>Rechercher des facteurs individuels, sans imposer une liste d’interdits</h4><table><thead><tr><th>Facteur possible</th><th>Conseil pratique</th></tr></thead><tbody><tr><td>Sommeil irrégulier, dette ou excès de sommeil</td><td>Horaires réguliers ; explorer un trouble du sommeil si nécessaire.</td></tr><tr><td>Jeûne, repas sautés, déshydratation</td><td>Repas et hydratation réguliers, adaptés au patient.</td></tr><tr><td>Stress ou relâchement après stress</td><td>Identifier le rythme ; <span class=\"nc-green_bg\">relaxation</span>, activité physique et soutien selon besoin.</td></tr><tr><td>Règles / variations hormonales</td><td>Documenter le lien dans l’<span class=\"nc-blue nc-bold\">agenda</span> ; migraine menstruelle si <span class=\"nc-yellow_bg\">crises</span> dans la fenêtre de J−2 à J+3, au moins 2 cycles sur 3.</td></tr><tr><td>Alcool, stimuli sensoriels, certains aliments</td><td>Retenir un déclencheur seulement si le lien est reproductible ; pas de régime restrictif systématique.</td></tr><tr><td>Prises médicamenteuses fréquentes</td><td>Compter les jours et revoir la stratégie avant chronicisation.</td></tr></tbody></table><ul><li>Le terrain familial explique une susceptibilité, pas la responsabilité du patient dans la maladie.</li><li>Fringale, <span class=\"nc-blue_bg\">bâillements</span> ou <span class=\"nc-red nc-bold\">photophobie</span> peuvent être des <strong>prodromes</strong> : un aliment ou une lumière peut être accusé à tort de déclencher la crise.</li><li>L’<span class=\"nc-blue nc-bold\">agenda</span> permet une observation sur plusieurs semaines ; éviter une surveillance anxieuse de chaque sensation.</li><li>Le contrôle des facteurs favorisants accompagne un traitement <span class=\"nc-red nc-bold\">efficace</span>, il ne le remplace pas.</li></ul></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://sfemc.fr/wp-content/uploads/2023/02/recommandations-2021-pour-le-diagnostic-et-la-prise-en-ch_2022_la-presse-m-d.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Recommandations 2021, traitement des crises (publication 2022, figure 1)</a></li></ul><p>Facteurs distingués des prodromes ; prévention personnalisée plutôt qu’évictions alimentaires systématiques.</p></details>","frequence":0},{"id":"99-13","rang":"A","rubrique":"Étiologies","titre":"Connaître l'existence de céphalées induites par les médicaments chez le migraineux","contenu":"<div class=\"notion-course\"><h4>Deux mécanismes à distinguer</h4><table><thead><tr><th>Situation</th><th>Exemple / démarche</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Céphalée</span> provoquée par une substance</td><td>Lien temporel avec médicament vasodilatateur, dérivé nitré ou autre substance ; revoir indication, dose et alternative avec le prescripteur.</td></tr><tr><td><span class=\"nc-red nc-bold\">Céphalée</span> par <span class=\"nc-orange_bg nc-bold\">abus médicamenteux</span></td><td>Surconsommation répétée des <span class=\"nc-pink\">traitements</span> de crise chez un patient ayant déjà une <span class=\"nc-red nc-bold\">céphalée</span> primaire ; favorise la chronicisation.</td></tr></tbody></table><h4>Les seuils diagnostiques ne sont pas des objectifs de consommation</h4><p><span class=\"nc-red nc-bold\">Céphalée</span> <strong>≥ 15 jours/mois</strong> avec surconsommation régulière pendant <strong>plus de 3 mois</strong>, sans meilleure explication :</p><table><thead><tr><th>Traitement de crise</th><th>Seuil de surconsommation</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Triptans</span>, <span class=\"nc-red nc-bold\">opioïdes</span>, ergotés, antalgiques combinés</td><td>≥ 10 jours/mois.</td></tr><tr><td><span class=\"nc-green nc-bold\">Paracétamol</span>, <span class=\"nc-green nc-bold\">aspirine</span>, <span class=\"nc-green nc-bold\">AINS</span> seuls</td><td>≥ 15 jours/mois.</td></tr><tr><td>Plusieurs classes utilisées en alternance</td><td>Un cumul peut constituer un abus même si chaque classe paraît sous son seuil ; faire l’inventaire de tous les jours de prise.</td></tr></tbody></table><h4>Que faire ?</h4><ol><li>Expliquer le cercle douleur–prises répétées, sans culpabiliser ; noter jours de <span class=\"nc-red nc-bold\">céphalée</span> et jours de traitement.</li><li>Confirmer la <span class=\"nc-red nc-bold\">céphalée</span> initiale et rechercher des drapeaux rouges ; <span class=\"nc-red\">migraine</span> chronique et abus peuvent coexister.</li><li>Organiser réduction/sevrage et traitement préventif adaptés ; prévenir une aggravation transitoire et planifier le suivi.</li><li>Recourir à un accompagnement spécialisé pour <span class=\"nc-red nc-bold\">opioïdes</span>, dépendance, comorbidités ou échec ; ne pas imposer un arrêt <span class=\"nc-red nc-bold\">brutal</span> non encadré des substances à risque de sevrage.</li></ol><div class=\"callout\"><p>Pour prévenir l’abus, viser généralement <strong>au plus 8 jours de <span class=\"nc-pink\">traitements</span> de crise par mois</strong>. Au-delà, réévaluer plutôt qu’attendre d’atteindre les seuils de 10 ou 15 jours. Compter des jours, pas seulement des comprimés.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418171be27eec2430b18ac?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée chronique quotidienne</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://sfemc.fr/wp-content/uploads/2023/02/recommandations-2021-pour-le-diagnostic-et-la-prise-en-ch_2022_la-presse-m-d.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Recommandations 2021, traitement des crises (publication 2022, figure 1)</a></li></ul><p>Prévention à 8 jours distinguée des seuils diagnostiques 10/15 jours ; alternance de classes et double diagnostic explicités.</p></details>","frequence":1},{"id":"99-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux du traitement","contenu":"<div class=\"notion-course\"><h4>Le traitement dépend du diagnostic</h4><table><thead><tr><th>Maladie</th><th>Crise / accès</th><th>Prévention / traitement continu</th></tr></thead><tbody><tr><td>Migraine</td><td><span class=\"nc-pink_bg\">AINS</span> ou <span class=\"nc-pink_bg\">triptan</span> selon <span class=\"nc-brown_bg\">intensité</span>, réponse antérieure et contre-indications ; traitement précoce de la céphalée.</td><td><span class=\"nc-blue nc-bold\">Agenda</span>, mesures régulières et traitement préventif si handicap/fréquence/consommation le justifient.</td></tr><tr><td>AVF</td><td>Oxygène 100 % à haut débit ou <span class=\"nc-pink nc-bold\">sumatriptan</span> sous-cutané si compatible avec le terrain.</td><td><span class=\"nc-pink_bg\">Vérapamil</span> avec surveillance ECG ; traitement transitoire et autres options en neurologie.</td></tr><tr><td>Névralgie du trijumeau</td><td>Les accès sont trop courts pour un antalgique pris à chaque décharge ; éviter les stimuli gênants pendant la mise en route.</td><td><span class=\"nc-pink_bg\">Carbamazépine</span> en première intention ; alternatives puis discussion neurochirurgicale si échec/intolérance.</td></tr><tr><td>Douleur secondaire / locale</td><td>Antalgie adaptée et traitement de la cause.</td><td>Ne pas répéter un traitement symptomatique sans résoudre le foyer ou la cause.</td></tr></tbody></table><h4>AVF : soulager rapidement, prévenir pendant la période active</h4><ul><li><strong>Oxygène 100 %</strong> par masque à haute concentration avec réservoir, typiquement 12–15 L/min pendant 15–20 min, dès le début ; respect des règles de sécurité de l’oxygène.</li><li><strong><span class=\"nc-pink nc-bold\">Sumatriptan</span> sous-cutané 6 mg</strong> : action rapide, au maximum 2 injections/24 h selon prescription ; vérifier notamment contre-indications cardiovasculaires et associations.</li><li><strong><span class=\"nc-pink_bg\">Vérapamil</span></strong> : initiation et augmentation avec <span class=\"nc-blue nc-bold\">ECG</span> avant traitement puis après augmentations, à cause du risque de trouble conductif.</li><li>Une courte corticothérapie ou une infiltration du grand occipital peut servir de transition, sur décision spécialisée ; suivi du retentissement psychique.</li></ul><h4>Névralgie du trijumeau : sécuriser l’escalade</h4><ul><li><span class=\"nc-pink_bg\">Carbamazépine</span> avec titration progressive et surveillance clinique/biologique (<span class=\"nc-blue nc-bold\">NFS</span>, foie, <span class=\"nc-blue nc-bold\">natrémie</span> selon protocole), interactions et risques cutanés. Une éruption suspecte nécessite un avis rapide.</li><li>Oxcarbazépine ou autres alternatives sur avis spécialisé si intolérance/échec ; surveiller notamment la <span class=\"nc-blue nc-bold\">natrémie</span>.</li><li>Si douleur reste invalidante : vérifier diagnostic, observance et IRM avant discussion neurochirurgicale.</li><li>Décompression microvasculaire si conflit compressif concordant et patient opérable ; techniques percutanées ou radiochirurgie dans d’autres situations, en expliquant récidive et risque sensitif.</li><li>L’âge seul ne décide pas du geste ; les préférences, comorbidités et résultats de l’imagerie comptent.</li></ul><div class=\"callout\"><p>Les opioïdes ne sont pas le traitement usuel des céphalées primaires. La réponse à un médicament ne dispense jamais d’un bilan si la douleur est atypique.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e9835eec8613b4ca45?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Algie vasculaire de la face</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://sfemc.fr/wp-content/uploads/2023/02/recommandations-2021-pour-le-diagnostic-et-la-prise-en-ch_2022_la-presse-m-d.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Recommandations 2021, traitement des crises (publication 2022, figure 1)</a></li><li><a href=\"https://campus.neurochirurgie.fr/article1715.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de neurochirurgie · Item 99, arbre décisionnel figure 7.7</a></li></ul><p>Stratégies des trois maladies distinguées ; oxygène au masque à réservoir, contrôle ECG du vérapamil et critères de chirurgie précisés.</p></details>","frequence":0},{"id":"99-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","contenu":"<div class=\"notion-course\"><h4>1 · Construire une prescription utilisable dès la prochaine crise</h4><p>Noter jours de <span class=\"nc-red nc-bold\">céphalée</span>, <span class=\"nc-brown_bg\">intensité</span>, aura, handicap, médicaments/doses et réponse dans un <strong><span class=\"nc-blue nc-bold\">agenda</span></strong>. Vérifier contre-indications, <span class=\"nc-green_bg\">grossesse</span>/projet, <span class=\"nc-pink\">traitements</span> associés et préférences. Le plan de crise doit préciser quoi prendre, quand, puis le recours si la réponse est insuffisante.</p><table><thead><tr><th>Situation chez l’adulte</th><th>Stratégie de crise</th></tr></thead><tbody><tr><td>Crise légère, sans contre-indication</td><td><span class=\"nc-pink_bg\">AINS</span> en première prise ; <span class=\"nc-pink_bg\">triptan</span> de secours après environ 1 h si réponse insuffisante, selon le plan prescrit.</td></tr><tr><td>Crise <span class=\"nc-pink_bg\">modérée</span>/sévère ou échec connu de l’<span class=\"nc-pink_bg\">AINS</span></td><td><span class=\"nc-pink_bg\">Triptan</span> d’emblée ; <span class=\"nc-pink_bg\">AINS</span> de secours après environ 1 h si nécessaire et compatible.</td></tr><tr><td>Aura habituelle</td><td><span class=\"nc-pink_bg\">AINS</span> possible au début de l’aura ; <span class=\"nc-pink_bg\">triptan</span> au début de la <span class=\"nc-red nc-bold\">céphalée</span>, même si l’aura persiste. Le <span class=\"nc-pink_bg\">triptan</span> n’est pas un traitement préventif de l’<span class=\"nc-brown_bg\">aura isolée</span>.</td></tr><tr><td>Réponse insuffisante ou récidives malgré monothérapie bien utilisée</td><td>Réévaluer délai, dose, voie et diagnostic ; essayer un autre <span class=\"nc-pink_bg\">triptan</span> ou l’association AINS + <span class=\"nc-pink_bg\">triptan</span> selon plan médical.</td></tr><tr><td><span class=\"nc-blue_bg\">Nausées</span> / <span class=\"nc-blue_bg\">vomissements</span></td><td>Adapter la voie et discuter un antiémétique. Une forme non orale peut être utile.</td></tr><tr><td>Contre-indication ou mauvaise tolérance</td><td>Choisir une alternative adaptée au terrain ; paracétamol éventuellement si options habituelles impossibles, avis spécialisé si échecs.</td></tr></tbody></table><h4>2 · Respecter les règles de prise</h4><ul><li>Traiter <strong>tôt au début de la <span class=\"nc-red nc-bold\">céphalée</span></strong>, à dose <span class=\"nc-red nc-bold\">efficace</span> prescrite, plutôt que multiplier de petites prises tardives.</li><li>AINS : vérifier risques digestif, rénal, cardiovasculaire, interactions et <span class=\"nc-green_bg\">grossesse</span> ; ne pas associer deux AINS.</li><li><span class=\"nc-red nc-bold\">Triptans</span> : vérifier maladie vasculaire, HTA non contrôlée et associations contre-indiquées ; ne pas combiner différents <span class=\"nc-red nc-bold\">triptans</span> ou ergotés sans respecter les délais du RCP.</li><li>Une seconde prise du même <span class=\"nc-pink_bg\">triptan</span> se discute surtout en cas de récidive après réponse initiale, avec intervalle et maximum du RCP. En cas d’échec complet, suivre le recours prévu plutôt que répéter automatiquement.</li><li>Évaluer sur plusieurs crises : soulagement à 2 h, reprise des activités, absence de récidive gênante et bonne tolérance.</li><li>Éviter <span class=\"nc-red nc-bold\">opioïdes</span> et associations antalgiques avec <span class=\"nc-red nc-bold\">caféine</span> ; prévenir la surconsommation en comptant les jours.</li></ul><h4>3 · Quand proposer un traitement préventif ?</h4><ul><li><span class=\"nc-red\">Crises</span> fréquentes, invalidantes ou prolongées malgré un traitement de crise optimisé, selon les attentes du patient.</li><li>Besoin de <span class=\"nc-pink\">traitements</span> de crise proche de ou supérieur à <span class=\"nc-pink nc-bold\">8 jours/mois</span>, notamment durablement ; risque d’abus.</li><li><span class=\"nc-red_bg\">Migraine chronique</span>, contre-indications ou échecs des <span class=\"nc-pink\">traitements</span> de crise : avis adapté.</li></ul><table><thead><tr><th>Option</th><th>Choix selon le terrain</th></tr></thead><tbody><tr><td>Bêtabloquant : <span class=\"nc-pink_bg\">propranolol</span>, <span class=\"nc-pink_bg\">métoprolol</span></td><td>Option classique, surtout <span class=\"nc-red\">migraine</span> épisodique ; vérifier asthme, bradycardie et troubles conductifs.</td></tr><tr><td><span class=\"nc-pink\">Amitriptyline</span> / candésartan</td><td>Selon comorbidités et tolérance ; certains usages sont hors AMM. <span class=\"nc-pink\">Amitriptyline</span> : sédation/effets anticholinergiques ; candésartan : TA, rein, kaliémie et contre-indications liées à la <span class=\"nc-green_bg\">grossesse</span>.</td></tr><tr><td>Topiramate</td><td>Option <span class=\"nc-red nc-bold\">efficace</span> mais sélection prudente : troubles cognitifs, poids, lithiases et risque majeur pour la <span class=\"nc-green_bg\">grossesse</span>. Respecter le programme ANSM.</td></tr><tr><td><span class=\"nc-pink\">Traitements</span> ciblant le CGRP / gépants</td><td>Options spécialisées selon indication, autorisation et accès ; ne pas confondre critères d’AMM et de remboursement.</td></tr><tr><td><span class=\"nc-pink_bg\">Toxine botulique</span> de type A</td><td>Option spécialisée dans la <span class=\"nc-red\">migraine</span> chronique ; pas le traitement usuel d’une <span class=\"nc-red\">migraine</span> épisodique.</td></tr></tbody></table><h4>4 · Suivre et adapter</h4><ol><li>Débuter progressivement si nécessaire ; définir avec le patient un objectif de diminution des jours douloureux et du handicap.</li><li>Réévaluer après une durée suffisante à dose tolérée, souvent 2–3 mois pour les <span class=\"nc-pink\">traitements</span> oraux classiques. Une baisse d’environ 50 % des crises/jours migraineux est un repère, avec appréciation de la qualité de vie.</li><li>Si inefficace : vérifier diagnostic, observance, dose, durée et abus avant de changer ; si <span class=\"nc-red nc-bold\">efficace</span> : poursuivre plusieurs mois puis discuter une réduction progressive.</li><li>Associer régularité du <span class=\"nc-green_bg\">sommeil</span>/<span class=\"nc-blue_bg\">repas</span>, activité physique, <span class=\"nc-green_bg\">relaxation</span> ou prise en charge comportementale selon besoin.</li></ol><div class=\"callout\"><p><strong><span class=\"nc-pink_bg\">Topiramate</span> en prévention de la <span class=\"nc-red\">migraine</span></strong> : contre-indiqué pendant la <span class=\"nc-green_bg\">grossesse</span> et chez une femme pouvant procréer sans contraception hautement <span class=\"nc-red nc-bold\">efficace</span>. Test de <span class=\"nc-green_bg\">grossesse</span> avant traitement, information et suivi spécialisé, attestation annuelle selon programme ANSM ; contraception pendant le traitement et au moins 4 semaines après. Vérifier les interactions contraceptives et privilégier les alternatives adaptées.</p></div><details><summary>Enfant, grossesse et allaitement</summary><p>Adapter le plan à l’âge, au poids et à la situation reproductive ; la prescription adulte ne se transpose pas automatiquement. Pendant la <span class=\"nc-green_bg\">grossesse</span>, réévaluer tout traitement : pas d’automédication par AINS, qui sont contre-indiqués à partir de 24 SA. Le choix d’un traitement de crise ou préventif nécessite une vérification spécifique du médicament et du terme.</p></details></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418171be27eec2430b18ac?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée chronique quotidienne</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://sfemc.fr/wp-content/uploads/2023/02/recommandations-2021-pour-le-diagnostic-et-la-prise-en-ch_2022_la-presse-m-d.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Recommandations 2021, traitement des crises (publication 2022, figure 1)</a></li><li><a href=\"https://sfemc.fr/professionnels/recommandations/recommandations-pour-le-diagnostic-et-la-prise-en-charge-de-la-migraine-chez-ladulte-traitement-preventif/\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Recommandations, traitement préventif de la migraine</a></li><li><a href=\"https://sfemc.fr/professionnels/recommandations/migraine-treatment-position-paper-of-the-french-headache-society-article-en-anglais/\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Actualisation de la place des traitements de la migraine, position paper</a></li><li><a href=\"https://ansm.sante.fr/uploads/2024/12/11/20241211-topiramate-guide-professionnels-sante.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Topiramate : programme de prévention des grossesses, guide 2024</a></li><li><a href=\"https://ansm.sante.fr/uploads/2021/01/07/rappel-bonusageains130821.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Rappel du bon usage des AINS</a></li></ul><p>Stratégie SFEMC mise en étapes ; nouveautés spécialisées distinguées des règles d’accès et topiramate actualisé selon ANSM.</p></details>","frequence":0},{"id":"99-16","rang":"A","rubrique":"Prise en charge","titre":"Savoir conseiller un patient migraineux","contenu":"<div class=\"notion-course\"><h4>Donner au patient un plan simple et des repères</h4><ul><li>Expliquer que la <span class=\"nc-red\">migraine</span> est une maladie neurologique ; un examen normal n’invalide pas la douleur.</li><li>Tenir un <span class=\"nc-blue nc-bold\">agenda</span> simple : jours de <span class=\"nc-red nc-bold\">céphalée</span>, aura, médicaments, retentissement et facteurs reproductibles.</li><li>Prendre le traitement de crise au bon moment, connaître le recours prévu et éviter la multiplication des prises.</li><li>Maintenir <span class=\"nc-green_bg\">sommeil</span>, <span class=\"nc-blue_bg\">repas</span>, hydratation et activité physique réguliers ; proposer <span class=\"nc-green_bg\">relaxation</span> ou accompagnement si besoin.</li><li>Préparer une ordonnance adaptée aux déplacements, aux <span class=\"nc-blue_bg\">vomissements</span> éventuels et aux contraintes professionnelles.</li></ul><h4>Réduire le risque vasculaire associé</h4><ul><li>Encourager l’<strong>arrêt du tabac</strong> ; rechercher et traiter HTA, dyslipidémie, diabète et autres facteurs selon le terrain.</li><li>La <span class=\"nc-orange_bg\">migraine avec aura</span> est associée à un sur-risque d’AVC ischémique, particulièrement avec tabac et contraception estroprogestative. Le risque absolu reste à apprécier individuellement.</li><li>En cas de <strong><span class=\"nc-orange_bg\">migraine avec aura</span></strong>, éviter la contraception estroprogestative : discuter une méthode progestative ou non hormonale adaptée. Une aura nouvellement apparue sous contraception impose une réévaluation médicale.</li><li>Une <span class=\"nc-green_bg\">grossesse</span> envisagée doit faire revoir le traitement préventif avant conception, notamment topiramate et candésartan.</li></ul><h4>Quand reconsulter ?</h4><table><thead><tr><th>Situation</th><th>Délai</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Coup de tonnerre</span>, déficit inhabituel, confusion, fièvre/raideur, perte visuelle</td><td>Urgence ; ne pas simplement répéter le traitement habituel.</td></tr><tr><td><span class=\"nc-red\">Crises</span> plus fréquentes, traitement de crise &gt; <span class=\"nc-pink nc-bold\">8 jours/mois</span>, effets indésirables</td><td>Consultation pour réévaluer le plan et envisager prévention.</td></tr><tr><td>Changement durable du profil, aura nouvelle, <span class=\"nc-red nc-bold\">céphalée</span> pendant <span class=\"nc-green_bg\">grossesse</span>/post-partum</td><td>Évaluation rapide, urgente selon les signes.</td></tr></tbody></table><p>Lors du suivi, demander ce que le patient n’arrive plus à faire. La réussite se mesure aussi au retour aux activités et à la confiance dans le plan de prise en charge.</p></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d9418171be27eec2430b18ac?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalée chronique quotidienne</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://sfemc.fr/wp-content/uploads/2023/02/recommandations-2021-pour-le-diagnostic-et-la-prise-en-ch_2022_la-presse-m-d.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">SFEMC · Recommandations 2021, traitement des crises (publication 2022, figure 1)</a></li><li><a href=\"https://ansm.sante.fr/uploads/2024/12/11/20241211-topiramate-guide-professionnels-sante.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">ANSM · Topiramate : programme de prévention des grossesses, guide 2024</a></li></ul><p>Conseils vasculaires, contraception et plan de reconsultation explicités ; pas de conseils alimentaires universels.</p></details>","frequence":0},{"id":"99-17","rang":"B","rubrique":"Contenu multimédia","titre":"A partir d'une vidéo d'interrogatoire, évoquer le diagnostic de migraine, d'algie vasculaire de la face, de névralgie du trijumeau","contenu":"<div class=\"notion-course\"><h4>Grille pour analyser un interrogatoire filmé</h4><ol><li>Repérer durée et fréquence <strong>sans traitement</strong>, puis ancienneté et caractère stéréotypé.</li><li>Noter localisation, type de douleur, déclenchement et <span class=\"nc-brown_bg\">signes associés</span>.</li><li>Observer le comportement décrit : retrait au calme, <span class=\"nc-yellow_bg\">agitation</span> ou évitement du contact.</li><li>Rechercher les questions de sécurité oubliées : début <span class=\"nc-red nc-bold\">brutal</span>, neurologie, œil, fièvre, terrain, <span class=\"nc-pink\">traitements</span>.</li><li>Formuler une hypothèse avec ses arguments et ce qui manque pour la confirmer ; préciser l’examen et le bilan nécessaires.</li></ol><table><thead><tr><th>Indices à relever</th><th>Hypothèse à argumenter</th></tr></thead><tbody><tr><td><span class=\"nc-yellow_bg\">Crises</span> de plusieurs heures, pulsatiles, activité aggravante, <span class=\"nc-blue_bg\">nausées</span> ou photo + <span class=\"nc-red nc-bold\">phonophobie</span>, repos au calme</td><td>Migraine ; rechercher aura progressive/réversible et nombre de <span class=\"nc-yellow_bg\">crises</span>.</td></tr><tr><td>Douleur <span class=\"nc-blue_bg\">orbitaire</span> <span class=\"nc-blue_bg\">unilatérale</span> <span class=\"nc-yellow_bg\">très intense</span>, 15–180 min, <span class=\"nc-orange_bg\">larmoiement</span>/<span class=\"nc-orange_bg\">rhinorrhée</span> du même côté et <span class=\"nc-yellow_bg\">agitation</span></td><td>AVF ; rechercher périodes, fréquence, Horner <span class=\"nc-red nc-bold\">récent</span> et bilan IRM.</td></tr><tr><td>Décharges de quelques secondes dans V2/V3, déclenchées par <span class=\"nc-red nc-bold\">parole</span> ou brossage, <span class=\"nc-red nc-bold\">zone gâchette</span></td><td>Névralgie du trijumeau ; examen sensitif et IRM pour classification.</td></tr></tbody></table><h4>Vignettes écrites d’entraînement</h4><details><summary>Cas 1 · « Je me couche dans le noir »</summary><p>Depuis l’adolescence, épisodes de 12 heures, pulsatiles, aggravés en montant les <span class=\"nc-red nc-bold\">escaliers</span>, avec <span class=\"nc-blue_bg\">nausées</span> et gêne à la lumière. Hypothèse : migraine. Compléter fréquence, critères, aura, consommation médicamenteuse, examen et absence de <span class=\"nc-brown_bg\">signes</span> nouveaux.</p></details><details><summary>Cas 2 · « Je marche pendant la crise »</summary><p>Pendant plusieurs semaines, douleur autour d’un œil durant 45 minutes, plusieurs fois par jour, avec <span class=\"nc-orange_bg\">larmoiement</span> et nez bouché du même côté. Hypothèse : AVF. Confirmer fréquence, durée, caractère stéréotypé, examen et IRM ; distinguer un Horner douloureux <span class=\"nc-red nc-bold\">récent</span> nécessitant bilan vasculaire urgent.</p></details><details><summary>Cas 3 · « Me brosser les dents déclenche une décharge »</summary><p>Décharges de 10 secondes dans la joue et la mâchoire, provoquées par un effleurement ; le patient évite de manger. Hypothèse : névralgie du trijumeau. Rechercher <span class=\"nc-brown_bg\">signes</span> <span class=\"nc-green_bg\">sensitifs</span>, autres nerfs crâniens, retentissement nutritionnel et organiser l’IRM.</p></details><div class=\"callout\"><p>Ces cas sont des <strong>vignettes écrites</strong> pour travailler la compétence d’interrogatoire. Aucune vidéo de consultation n’est intégrée à cette fiche ; la grille peut être utilisée avec une vidéo pédagogique de ton enseignement.</p></div></div><details class=\"course-references\"><summary>Sources et compléments</summary><p>Relecture du 12 octobre 2026. Couleurs reprises uniquement des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418138ae0cd014ff301348?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Migraine</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181e9835eec8613b4ca45?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Algie vasculaire de la face</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d94181958e94c571af6d858e?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Névralgies faciales et crâniennes</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face\" target=\"_blank\" rel=\"noopener noreferrer\">Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face</a></li><li><a href=\"https://campus.neurochirurgie.fr/article1715.html\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de neurochirurgie · Item 99, arbre décisionnel figure 7.7</a></li></ul><p>Objectif entraîné par une grille d’observation et trois cas ; absence de vidéo intégrée explicitement signalée.</p></details>","frequence":0}],"astuces":[{"type":"warning","titre":"Une nouvelle douleur change le raisonnement","contenu":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Coup de tonnerre</span>, déficit, <span class=\"nc-blue_bg nc-bold\">fièvre</span>, baisse visuelle ou Horner <span class=\"nc-blue nc-bold\">douloureux</span> <span class=\"nc-red nc-bold\">récent</span> : rechercher une cause secondaire même chez un <span class=\"nc-brown_bg\">migraineux</span> connu.</p></div>"},{"type":"info","titre":"Trois durées, trois comportements","contenu":"<div class=\"notion-course\"><p><span class=\"nc-red\">Migraine</span> : heures et repos. AVF : dizaines de minutes et <span class=\"nc-yellow_bg\">agitation</span>. Névralgie du V : secondes et évitement du contact. Ce sont des repères à confronter aux <span class=\"nc-red nc-bold\">critères</span> complets.</p></div>"},{"type":"warning","titre":"Compter les jours de prise","contenu":"<div class=\"notion-course\"><p>Le repère de prévention est généralement ≤ <span class=\"nc-pink nc-bold\">8 jours/mois</span> ; les seuils <span class=\"nc-red nc-bold\">diagnostiques</span> d’abus sont différents. Anticiper la prévention avant chronicisation.</p></div>"}],"strategie":{"urgence":"<div class=\"notion-course\"><ul><li>Rechercher drapeaux rouges et menace visuelle/neurologique/infectieuse.</li><li>Orienter sans attendre un bilan programmé si un signe d’alarme est présent.</li></ul></div>","redflags":"<div class=\"notion-course\"><ul><li>Douleur nouvelle brutale, déficit inhabituel, œil rouge avec baisse visuelle ou Horner <span class=\"nc-blue nc-bold\">douloureux</span> <span class=\"nc-red nc-bold\">récent</span>.</li><li>Douleur faciale/otalgie persistante, <span class=\"nc-red nc-bold\">lésion</span> indurée ou <span class=\"nc-brown_bg\">signes</span> d’infection profonde.</li></ul></div>","principes":"<div class=\"notion-course\"><ul><li>Diagnostiquer par la chronologie, les <span class=\"nc-brown_bg\">signes associés</span> et l’examen ; bilan ciblé.</li><li>Adapter crise et prévention à la maladie, au terrain et aux risques.</li><li><span class=\"nc-blue nc-bold\">Agenda</span> et suivi pour efficacité, handicap, tolérance et jours de prise.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/34b37f85d9418045b56ae76d44b6cb51?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-10-item-99-migraine-nevralgie-du-trijumeau-et-algies-de-la-face","label":"Collège des enseignants de neurologie · Item 99 — Migraine et algies de la face ↗"},{"href":"https://campus.neurochirurgie.fr/article1715.html","label":"Collège de neurochirurgie · Item 99, arbre décisionnel figure 7.7 ↗"},{"href":"https://sfemc.fr/professionnels/recommandations/migraine-treatment-position-paper-of-the-french-headache-society-article-en-anglais/","label":"SFEMC · Actualisation de la place des traitements de la migraine, position paper ↗"},{"href":"https://archives.uness.fr/sites/campus-unf3s-2015/UNF3Smiroir/campus-numeriques/orl/enseignement/migraine/site/html/6.html","label":"Collège français d’ORL · Douleurs de la face, sémiologie (archive UNESS 2014) ↗"},{"href":"https://ichd-3.org/1-migraine/1-2-migraine-with-aura/","label":"International Headache Society · ICHD-3 — Migraine avec aura ↗"},{"href":"https://ichd-3.org/3-trigeminal-autonomic-cephalalgias/3-1-cluster-headache/3-1-2-chronic-cluster-headache/","label":"International Headache Society · ICHD-3 — Algie vasculaire de la face chronique ↗"},{"href":"https://sfemc.fr/wp-content/uploads/2023/02/recommandations-2021-pour-le-diagnostic-et-la-prise-en-ch_2022_la-presse-m-d.pdf","label":"SFEMC · Recommandations 2021, traitement des crises (publication 2022, figure 1) ↗"},{"href":"https://sfemc.fr/professionnels/recommandations/recommandations-pour-le-diagnostic-et-la-prise-en-charge-de-la-migraine-chez-ladulte-traitement-preventif/","label":"SFEMC · Recommandations, traitement préventif de la migraine ↗"},{"href":"https://ansm.sante.fr/uploads/2024/12/11/20241211-topiramate-guide-professionnels-sante.pdf","label":"ANSM · Topiramate : programme de prévention des grossesses, guide 2024 ↗"},{"href":"https://ansm.sante.fr/uploads/2021/01/07/rappel-bonusageains130821.pdf","label":"ANSM · Rappel du bon usage des AINS ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Douleur nouvelle ou signes d’alerte ?","detail":"<ul><li>Dater début, durée et répétition.</li><li>Examiner neurologie, œil, bouche et ORL.</li><li>Coup de tonnerre, déficit, fièvre, grossesse/post-partum, profil modifié ou terrain à risque.</li><li>Une céphalée primaire connue ne protège pas d’une cause secondaire.</li></ul>","branches":[{"label":"Urgence / suspicion secondaire","to":"urgent"},{"label":"Pas d’alerte après examen","to":"local"}]},{"id":"urgent","kind":"urgent","label":"Explorer la cause prioritaire sans délai","detail":"<ul><li>Imagerie et filière adaptées au tableau.</li><li>Protéger fonctions vitales et vision.</li><li>Horner douloureux récent : dissection ; œil rouge avec baisse visuelle : urgence ophtalmologique.</li><li>Après 50 ans avec claudication mâchoire/vision : artérite à cellules géantes.</li><li>Fièvre avec trismus/plancher gonflé : infection profonde.</li></ul>","branches":[]},{"id":"local","kind":"decision","label":"Existe-t-il un foyer local concordant ?","detail":"<ul><li>Examiner dents, muqueuses, nez, oreilles et ATM.</li><li>Chercher masse et adénopathie si douleur persistante.</li><li>Une douleur de joue n’est pas à elle seule une sinusite.</li></ul>","branches":[{"label":"Signes dentaires, sinusaux, buccaux ou auriculaires","to":"foyer"},{"label":"Pas de cause locale évidente","to":"duree"}]},{"id":"foyer","kind":"finish","label":"Orienter le bilan vers l’organe suspecté","detail":"<ul><li>Avis dentaire/ORL et examens ciblés.</li><li>Rechercher complication et cause tumorale.</li><li>Dents : percussion/thermique ; sinus : syndrome nasal ; oreille : otoscopie.</li><li>Otalgie persistante avec otoscopie normale : rechercher cause projetée, notamment VADS.</li><li>Pas de gestes dentaires répétés sans lésion explicative.</li></ul>","branches":[]},{"id":"duree","kind":"decision","label":"Quelle durée et quel comportement ?","detail":"<ul><li>Décrire une crise non traitée.</li><li>Rechercher signes associés et déclenchement.</li><li>La durée oriente ; elle ne remplace pas les critères complets.</li></ul>","branches":[{"label":"Secondes, décharges déclenchées au contact","to":"trijumeau"},{"label":"15–180 min, orbitaire avec agitation","to":"avf"},{"label":"Heures / jours ou douleur fréquente","to":"longue"}]},{"id":"trijumeau","kind":"finish","label":"Évoquer une névralgie du trijumeau","detail":"<ul><li>Cartographier territoire et zone gâchette.</li><li>Examiner sensibilité/nerfs crâniens et organiser IRM.</li><li>Classique, secondaire ou idiopathique selon bilan.</li><li>Suivre l’arbre thérapeutique dédié ; réponse à carbamazépine ne prouve pas la cause.</li></ul>","branches":[]},{"id":"avf","kind":"finish","label":"Confirmer les arguments d’AVF","detail":"<ul><li>Chercher signes autonomiques du même côté.</li><li>Préciser fréquence/périodes et organiser IRM.</li><li>Critères : ≥ 5 crises ; agitation et/ou signes autonomiques ; 1 tous les 2 jours à 8/j en période.</li><li>Crise : oxygène haut débit au masque à réservoir ou sumatriptan SC selon terrain.</li><li>Prévention : vérapamil avec ECG ; avis neurologique.</li></ul>","branches":[]},{"id":"longue","kind":"decision","label":"Le profil est-il migraineux ou tensif ?","detail":"<ul><li>Préciser activité, nausées et sensibilité sensorielle.</li><li>Compter jours douloureux et jours de prise.</li><li>Migraine et tension peuvent coexister ; les jours d’une migraine chronique ne sont pas tous typiques.</li></ul>","branches":[{"label":"Critères migraineux cohérents","to":"migraine"},{"label":"Profil de tension cohérent","to":"tension"},{"label":"Profil incertain / douleur persistante atypique","to":"doute"}]},{"id":"migraine","kind":"finish","label":"Confirmer migraine et rechercher aura","detail":"<ul><li>Vérifier critères et examen.</li><li>Préparer traitement de crise et prévention si nécessaire.</li><li>Aura habituelle progressive/réversible ; nouvelle manifestation déficitaire : reconsidérer l’urgence.</li><li>Agenda, facteurs individuels et retentissement guident le traitement.</li></ul>","branches":[]},{"id":"tension","kind":"finish","label":"Confirmer une céphalée de tension","detail":"<ul><li>Évaluer fréquence, stress et gêne fonctionnelle.</li><li>Prévenir la surconsommation d’antalgiques.</li><li>Pression bilatérale, pas d’aggravation à l’activité, pas de nausées/vomissements dans la forme épisodique.</li><li>Traitement adapté et réévaluation si modification du profil.</li></ul>","branches":[]},{"id":"doute","kind":"uncertain","label":"Reprendre le diagnostic avec un avis adapté","detail":"<ul><li>Rechercher cause secondaire et neuropathique.</li><li>Choisir imagerie/endoscopie selon hypothèse.</li><li>Douleur idiopathique persistante : diagnostic après bilan ; absence de lésion ≠ preuve psychiatrique.</li></ul>","branches":[]}]},"cards":[{"i":"f9e728c74b5e","n":99,"o":"99-1","u":"Epidémiologie","t":"Connaître l'épidémiologie des céphalées et douleurs de la face","q":"Quel est l’ordre de grandeur de la fréquence de migraine, AVF et névralgie du V ?","a":"<div class=\"notion-course\"><ul><li>Migraine : environ 15 % des adultes.</li><li>AVF : environ 1/1 000.</li><li>Névralgie du V : rare, incidence augmentant avec l’âge ; terrain ≠ critère obligatoire.</li></ul></div>"},{"i":"d20727f743dd","n":99,"o":"99-2","u":"Physiopathologie","t":"Connaître les bases physiopathologiques de la migraine","q":"Quel système et quel neuropeptide sont centraux dans la douleur migraineuse ?","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg\">Activation du système trigémino-vasculaire</span> avec libération notamment de <strong>CGRP</strong> ; sensibilisation possible. L’aura relève de la dépolarisation corticale envahissante.</p></div>"},{"i":"388a2f34b7f2","n":99,"o":"99-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d'une céphalée primaire","q":"Quels signes font sortir du raisonnement « céphalée primaire habituelle » ?","a":"<div class=\"notion-course\"><ul><li>Début <span class=\"nc-red nc-bold\">brutal</span>/maximal, nouveau déficit ou trouble de conscience.</li><li>Fièvre/méningisme, œil rouge avec baisse visuelle, Horner douloureux <span class=\"nc-red nc-bold\">récent</span>.</li><li>Profil nouveau/progressif, <span class=\"nc-green_bg\">grossesse</span>/post-partum, cancer/immunodépression, début après 50 ans ou déclenchement postural/<span class=\"nc-red nc-bold\">effort</span>.</li></ul></div>"},{"i":"6af108b61969","n":99,"o":"99-4","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic de migraine (avec ou sans aura)","q":"Quels sont les critères de migraine sans aura chez l’adulte ?","a":"<div class=\"notion-course\"><ol><li>≥ 5 <span class=\"nc-yellow_bg\">crises</span> de 4–72 h.</li><li>≥ 2 : <span class=\"nc-yellow_bg\">unilatérale</span>, <span class=\"nc-yellow_bg\">pulsatile</span>, <span class=\"nc-pink_bg\">modérée</span>/sévère, aggravée par activité courante.</li><li><span class=\"nc-blue_bg\">Nausées</span>/<span class=\"nc-blue_bg\">vomissements</span> OU photo + phonophobie.</li><li>Pas de meilleure explication.</li></ol></div>"},{"i":"82b232377aa9","n":99,"o":"99-4","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic de migraine (avec ou sans aura)","q":"Comment reconnaître une aura typique et son principal piège ?","a":"<div class=\"notion-course\"><ul><li>Symptômes <span class=\"nc-green_bg\">visuels</span>, <span class=\"nc-green_bg\">sensitifs</span> ou du langage, réversibles, souvent progressifs/successifs ; chaque symptôme habituellement 5–60 min.</li><li>Pas de déficit <span class=\"nc-red nc-bold\">moteur</span>, <span class=\"nc-red nc-bold\">rétinien</span> ou du tronc dans une aura typique.</li><li>Déficit nouveau/<span class=\"nc-red nc-bold\">brutal</span> ou atypique : évaluation urgente, ne pas présumer une aura.</li></ul></div>"},{"i":"285184613b6c","n":99,"o":"99-4","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic de migraine (avec ou sans aura)","q":"Combien de critères dynamiques faut-il pour une migraine avec aura ?","a":"<div class=\"notion-course\"><p>≥ 2 <span class=\"nc-yellow_bg\">crises</span> et ≥ 3 des 6 : extension ≥ 5 min, symptômes successifs, durée 5–60 min chacun, unilatéralité, symptôme <span class=\"nc-yellow_bg\">positif</span>, céphalée pendant ou dans les 60 min. Symptômes entièrement réversibles, pas de meilleure explication.</p></div>"},{"i":"ddcab93e1232","n":99,"o":"99-5","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic d'algie vasculaire de la face","q":"Quels indices orientent vers une algie vasculaire de la face ?","a":"<div class=\"notion-course\"><ul><li>Douleur <span class=\"nc-blue_bg\">orbitaire</span>/<span class=\"nc-blue_bg\">sus-orbitaire</span>/temporale <span class=\"nc-blue_bg\">unilatérale</span> très intense, 15–180 min.</li><li><span class=\"nc-brown_bg\">Signes</span> autonomiques ipsilatéraux et/ou <span class=\"nc-yellow_bg\">agitation</span>.</li><li>De 1 crise tous les 2 jours à 8/j en période active ; au moins 5 crises pour les critères formels.</li></ul></div>"},{"i":"8e52b6dbb819","n":99,"o":"99-5","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic d'algie vasculaire de la face","q":"Quand une AVF est-elle chronique ?","a":"<div class=\"notion-course\"><p>Crises depuis <strong>au moins 1 an</strong>, sans rémission ou avec rémissions de <strong>moins de 3 mois</strong>. Trois mois de crises seuls ne suffisent pas.</p></div>"},{"i":"1228d7630933","n":99,"o":"99-5","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic d'algie vasculaire de la face","q":"Quel piège devant un Horner douloureux récent ?","a":"<div class=\"notion-course\"><p>Rechercher une <strong><span class=\"nc-orange nc-bold\">dissection carotidienne</span></strong> en urgence, même sans déficit. Ne pas l’attribuer automatiquement à une AVF.</p></div>"},{"i":"f691a9fa41b6","n":99,"o":"99-6","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic de névralgie du trijumeau","q":"Quel est le profil d’une névralgie du trijumeau ?","a":"<div class=\"notion-course\"><ul><li>Décharges <span class=\"nc-red nc-bold\">unilatérales</span> dans le V, fraction de seconde à 2 min.</li><li>Stimulus indolore déclenchant une <span class=\"nc-red nc-bold\">zone gâchette</span> : effleurement, <span class=\"nc-red nc-bold\">parole</span>, <span class=\"nc-red nc-bold\">mastication</span>.</li><li>Examen neurologique et IRM pour rechercher une cause ; réponse à la <span class=\"nc-pink_bg\">carbamazépine</span> non suffisante.</li></ul></div>"},{"i":"4acd3a3aed66","n":99,"o":"99-6","u":"Diagnostic positif","t":"Conduire l'interrogatoire et réunir les arguments du diagnostic de névralgie du trijumeau","q":"Classique, secondaire ou idiopathique : comment classer une névralgie du V ?","a":"<div class=\"notion-course\"><ul><li>Classique : conflit compressif avec modifications morphologiques du nerf.</li><li>Secondaire : cause telle que SEP ou tumeur.</li><li>Idiopathique : pas de cause démontrée après bilan adapté.</li><li>Simple contact vasculaire ≠ preuve de causalité.</li></ul></div>"},{"i":"3253a773f537","n":99,"o":"99-7","u":"Diagnostic positif","t":"Connaître l'intrication migraines, céphalées de tension","q":"Quels indices favorisent une céphalée de tension épisodique ?","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg\">Pression</span>/serrement bilatéral, léger/modéré, sans aggravation à l’activité ; pas de <span class=\"nc-blue_bg\">nausée</span>/vomissement, au plus photo OU phonophobie. Durée 30 min–7 jours.</p></div>"},{"i":"1a0fc2f26cb9","n":99,"o":"99-7","u":"Diagnostic positif","t":"Connaître l'intrication migraines, céphalées de tension","q":"Quels sont les seuils de migraine chronique ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Céphalée</span> ≥ 15 jours/mois depuis &gt; 3 mois, dont ≥ 8 jours migraineux ou répondant au traitement spécifique, avec antécédent migraineux compatible. Les autres jours peuvent avoir un aspect tensif ; abus associé possible.</p></div>"},{"i":"408d51f18178","n":99,"o":"99-8","u":"Diagnostic positif","t":"Connaître les principales causes de douleur de la face","q":"Quels groupes de causes rechercher devant une douleur faciale ?","a":"<div class=\"notion-course\"><ul><li>Céphalée primaire ou neuropathie/névralgie.</li><li>Dentaire, ORL, oculaire, salivaire, osseuse/tumorale, ATM.</li><li>Vasculaire/inflammatoire : dissection, artérite à cellules géantes.</li><li>Idiopathique seulement après bilan adapté.</li></ul></div>"},{"i":"f25b0f48aaba","n":99,"o":"99-9","u":"Diagnostic positif","t":"Connaître la description clinique des algies d'origine dentaire, sinusienne et buccale","q":"Comment différencier douleur dentaire et douleur sinusienne ?","a":"<div class=\"notion-course\"><ul><li>Dentaire : stimulus thermique, <span class=\"nc-red nc-bold\">percussion</span>/<span class=\"nc-red_bg\">mastication</span> et foyer buccodentaire.</li><li>Sinusienne : syndrome nasal concordant, <span class=\"nc-blue_bg\">rhinorrhée</span>/obstruction ; topographie seule insuffisante.</li><li><span class=\"nc-red nc-bold\">Sinusite</span> <span class=\"nc-blue nc-bold\">maxillaire</span> unilatérale malodorante : rechercher foyer dentaire.</li></ul></div>"},{"i":"9865e6da3b2c","n":99,"o":"99-9","u":"Diagnostic positif","t":"Connaître la description clinique des algies d'origine dentaire, sinusienne et buccale","q":"Quels signes d’une infection buccodentaire imposent une prise en charge urgente ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue_bg\">Trismus</span>, dysphagie, voix modifiée, extension cervicale/plancher buccal ou gêne respiratoire : infection profonde et menace des voies aériennes. Signes orbitaires/neurologiques : <span class=\"nc-red nc-bold\">complication</span> possible.</p></div>"},{"i":"c65c29ceb71c","n":99,"o":"99-10","u":"Diagnostic positif","t":"Connaître la description clinique des céphalées d'origine auriculaire","q":"Quels signes orientent vers une otite externe ?","a":"<div class=\"notion-course\"><p><span class=\"nc-yellow_bg nc-bold\">Otalgie</span> à la pression du tragus/<span class=\"nc-red nc-bold\">traction du pavillon</span>, conduit <span class=\"nc-blue nc-bold\">inflammatoire</span> <span class=\"nc-blue nc-bold\">œdématié</span>, otorrhée. Terrain diabétique/<span class=\"nc-orange nc-bold\">immunodéprimé</span> et douleur profonde persistante : rechercher forme nécrosante.</p></div>"},{"i":"7c9e37f6b02d","n":99,"o":"99-10","u":"Diagnostic positif","t":"Connaître la description clinique des céphalées d'origine auriculaire","q":"Que faire devant une otalgie unilatérale persistante avec otoscopie normale ?","a":"<div class=\"notion-course\"><p>Chercher une douleur projetée dentaire, ATM ou pharyngolaryngée. Examen ORL, parfois nasofibroscopie, pour exclure notamment un cancer des VADS ; ne pas répéter des gouttes sans cause.</p></div>"},{"i":"45ba9cf42b91","n":99,"o":"99-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention devant une douleur de la face","q":"Quelles douleurs typiques de l’item 99 justifient une IRM ?","a":"<div class=\"notion-course\"><p>AVF et névralgie du trijumeau : <span class=\"nc-blue_bg\">IRM</span> ciblée pour une cause secondaire. <span class=\"nc-green_bg\">Migraine sans aura</span> ancienne typique et examen normal : pas d’imagerie <span class=\"nc-red nc-bold\">systématique</span>. Aura : le CEN propose au moins une <span class=\"nc-blue_bg\">IRM</span> ; <span class=\"nc-pink nc-bold\">urgence</span>/atypie : bilan adapté sans attendre.</p></div>"},{"i":"3a3528efa0bd","n":99,"o":"99-11","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention devant une douleur de la face","q":"Quel bilan initial devant une cause locale de douleur faciale ?","a":"<div class=\"notion-course\"><ul><li>Dentaire : examen puis clichés ciblés.</li><li><span class=\"nc-red nc-bold\">Sinusite</span> maxillaire simple : diagnostic clinique ; TDM si <span class=\"nc-red nc-bold\">complication</span>/atypie.</li><li>Salivaire : échographie selon <span class=\"nc-red nc-bold\">suspicion</span>.</li><li>ORL persistante : <span class=\"nc-blue_bg\">endoscopie</span>/imagerie/biopsie selon <span class=\"nc-red nc-bold\">lésion</span>.</li></ul></div>"},{"i":"937ae2a7f87b","n":99,"o":"99-12","u":"Étiologies","t":"Identifier les facteurs favorisants éventuels d'une migraine","q":"Quels conseils donner sur les déclencheurs de migraine ?","a":"<div class=\"notion-course\"><p>Régulariser <span class=\"nc-blue_bg\">sommeil</span>, <span class=\"nc-blue_bg\">repas</span> et hydratation ; identifier les liens reproductibles par <span class=\"nc-blue nc-bold\">agenda</span>. Pas d’éviction alimentaire systématique. Fringale/photophobie peuvent être des prodromes, pas des causes.</p></div>"},{"i":"661d4d3b81eb","n":99,"o":"99-13","u":"Étiologies","t":"Connaître l'existence de céphalées induites par les médicaments chez le migraineux","q":"Quels sont les critères de céphalée par abus médicamenteux ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-red nc-bold\">Céphalée</span> ≥ 15 j/mois et surconsommation <span class=\"nc-pink nc-bold\">&gt; 3 mois</span>.</li><li><span class=\"nc-red nc-bold\">Triptans</span>/<span class=\"nc-red nc-bold\">opioïdes</span>/ergotés/associations : ≥ 10 j/mois.</li><li>Antalgiques simples/<span class=\"nc-green nc-bold\">AINS</span> : ≥ 15 j/mois.</li><li>Plusieurs classes peuvent se cumuler ; compter les jours.</li></ul></div>"},{"i":"57afd4edbc04","n":99,"o":"99-13","u":"Étiologies","t":"Connaître l'existence de céphalées induites par les médicaments chez le migraineux","q":"Pourquoi le repère préventif de 8 jours diffère-t-il des seuils d’abus ?","a":"<div class=\"notion-course\"><p>Il sert à réévaluer tôt la stratégie et envisager une prévention. On n’attend pas 10 ou 15 jours de prise ni la chronicisation pour agir.</p></div>"},{"i":"a576a952f265","n":99,"o":"99-13","u":"Étiologies","t":"Connaître l'existence de céphalées induites par les médicaments chez le migraineux","q":"Quels principes de prise en charge d’un abus médicamenteux ?","a":"<div class=\"notion-course\"><p>Expliquer, utiliser l’<span class=\"nc-blue nc-bold\">agenda</span>, organiser réduction/sevrage et prévention, prévoir le suivi. Accompagnement spécialisé si <span class=\"nc-red nc-bold\">opioïdes</span>/dépendance ou situation complexe ; ne pas confondre avec simple arrêt non encadré.</p></div>"},{"i":"6b4b7ff15808","n":99,"o":"99-14","u":"Prise en charge","t":"Connaître les principes généraux du traitement","q":"Quel traitement rapide d’une crise d’AVF ?","a":"<div class=\"notion-course\"><ul><li>Oxygène 100 %, masque à haute concentration avec réservoir, 12–15 L/min environ 15–20 min.</li><li>Ou <span class=\"nc-pink\">sumatriptan</span> SC 6 mg, selon contre-indications ; maximum 2 injections/24 h selon prescription.</li></ul></div>"},{"i":"9329d2fb8351","n":99,"o":"99-14","u":"Prise en charge","t":"Connaître les principes généraux du traitement","q":"Quelle surveillance accompagne le vérapamil dans l’AVF ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">ECG</span> avant initiation et après augmentations de dose, pour risque de bradycardie/trouble conductif. Prescription et titration spécialisées.</p></div>"},{"i":"b0280684d323","n":99,"o":"99-14","u":"Prise en charge","t":"Connaître les principes généraux du traitement","q":"Quel traitement de première intention d’une névralgie du V et quelle surveillance ?","a":"<div class=\"notion-course\"><p><span class=\"nc-pink_bg\">Carbamazépine</span> progressivement titrée ; efficacité, tolérance, interactions, peau, <span class=\"nc-blue nc-bold\">NFS</span>, foie et <span class=\"nc-blue nc-bold\">natrémie</span> selon protocole. Alternatives spécialisées si échec/intolérance.</p></div>"},{"i":"ebb108b5803c","n":99,"o":"99-14","u":"Prise en charge","t":"Connaître les principes généraux du traitement","q":"Quand discuter une chirurgie d’une névralgie du trijumeau ?","a":"<div class=\"notion-course\"><p>Douleur invalidante malgré traitement adapté ou intolérance. Vérifier diagnostic et IRM. Conflit concordant + patient opérable : décompression possible ; sinon techniques percutanées/radiochirurgie selon balance bénéfice-risque et préférences.</p></div>"},{"i":"62063c3b5773","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Comment choisir la première prise d’une crise migraineuse ?","a":"<div class=\"notion-course\"><ul><li>Légère : <span class=\"nc-pink_bg\">AINS</span> si possible, <span class=\"nc-pink_bg\">triptan</span> de secours prévu si besoin.</li><li><span class=\"nc-pink_bg\">Modérée</span>/sévère ou <span class=\"nc-pink_bg\">AINS</span> inefficace : <span class=\"nc-pink_bg\">triptan</span>, <span class=\"nc-pink_bg\">AINS</span> de secours si compatible.</li><li>Prise précoce ; recours à environ 1 h selon plan SFEMC et prescription.</li></ul></div>"},{"i":"91b615d89aad","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Quand prendre le triptan si la crise commence par une aura ?","a":"<div class=\"notion-course\"><p>Au <strong>début de la <span class=\"nc-red nc-bold\">céphalée</span></strong>, même si l’aura persiste ; pas pour prévenir la douleur pendant une <span class=\"nc-brown_bg\">aura isolée</span>. <span class=\"nc-pink_bg\">AINS</span> possible au début de l’aura selon le plan.</p></div>"},{"i":"0d640fa90968","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Faut-il reprendre automatiquement le même triptan après un échec complet ?","a":"<div class=\"notion-course\"><p>Non. Suivre le recours prescrit. Une nouvelle prise se discute surtout si récidive après réponse initiale, avec intervalle et maximum propres au RCP. Vérifier dose, délai et contre-indications.</p></div>"},{"i":"ba6903064ad6","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Quand proposer un traitement préventif de la migraine ?","a":"<div class=\"notion-course\"><p>Handicap ou <span class=\"nc-red\">crises</span> fréquentes malgré prise en charge optimisée, consommation proche/&gt; 8 j/mois durable, <span class=\"nc-red_bg\">migraine chronique</span> ou <span class=\"nc-pink\">traitements</span> de crise inadaptés. Décision partagée selon terrain et retentissement.</p></div>"},{"i":"2d3992fe9f3a","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Quelles grandes options préventives connaître ?","a":"<div class=\"notion-course\"><p>Bêtabloquants, <span class=\"nc-pink\">amitriptyline</span>, candésartan, <span class=\"nc-pink_bg\">topiramate</span> selon terrain/risques ; options spécialisées ciblant CGRP et <span class=\"nc-pink_bg\">toxine botulique</span> pour <span class=\"nc-red\">migraine</span> chronique. Distinguer indication clinique, AMM et accès.</p></div>"},{"i":"3427361f3cf8","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Quelle règle majeure pour le topiramate en prévention de la migraine ?","a":"<div class=\"notion-course\"><p>Contre-indiqué pendant la <span class=\"nc-green_bg\">grossesse</span> et sans contraception hautement <span class=\"nc-red nc-bold\">efficace</span> chez une femme pouvant procréer. Programme ANSM : test préalable, information/suivi spécialisé, attestation annuelle ; contraception pendant et ≥ 4 semaines après.</p></div>"},{"i":"dbd812fc6839","n":99,"o":"99-15","u":"Prise en charge","t":"Connaître les modalités du traitement de la migraine et connaître les règles de prise d'un médicament","q":"Comment juger un traitement préventif ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">Agenda</span>, jours douloureux, handicap et tolérance après durée suffisante à dose adaptée, souvent 2–3 mois pour les <span class=\"nc-pink\">traitements</span> oraux classiques. Vérifier observance et abus avant de conclure à l’échec.</p></div>"},{"i":"5c57db38a9b0","n":99,"o":"99-16","u":"Prise en charge","t":"Savoir conseiller un patient migraineux","q":"Quels conseils vasculaires en cas de migraine avec aura ?","a":"<div class=\"notion-course\"><p>Arrêt du tabac, contrôle des facteurs vasculaires ; contraception estroprogestative à éviter, discuter méthode progestative ou non hormonale. Réévaluer toute aura nouvelle et tout projet de <span class=\"nc-green_bg\">grossesse</span>.</p></div>"},{"i":"e84f5e6bc27c","n":99,"o":"99-16","u":"Prise en charge","t":"Savoir conseiller un patient migraineux","q":"Quels éléments doivent figurer dans le plan remis à un migraineux ?","a":"<div class=\"notion-course\"><p><span class=\"nc-blue nc-bold\">Agenda</span>, traitement précoce avec recours précis, limites des jours de prise, règles de vie réalistes, suivi et signes d’alerte nécessitant une consultation urgente.</p></div>"},{"i":"402441f12206","n":99,"o":"99-17","u":"Contenu multimédia","t":"A partir d'une vidéo d'interrogatoire, évoquer le diagnostic de migraine, d'algie vasculaire de la face, de névralgie du trijumeau","q":"Crises de 12 h, escaliers aggravants, nausées et besoin de noir : quelle hypothèse ?","a":"<div class=\"notion-course\"><p>Migraine. Vérifier critères complets, aura, fréquence, examen, <span class=\"nc-brown_bg\">signes</span> nouveaux et jours de <span class=\"nc-pink\">traitements</span>. Un indice seul ne suffit pas.</p></div>"},{"i":"6a4057721c11","n":99,"o":"99-17","u":"Contenu multimédia","t":"A partir d'une vidéo d'interrogatoire, évoquer le diagnostic de migraine, d'algie vasculaire de la face, de névralgie du trijumeau","q":"Crises de 45 min autour d’un œil, larmoiement ipsilatéral et agitation : quelle hypothèse ?","a":"<div class=\"notion-course\"><p>AVF. Préciser répétition/périodes, rechercher cause secondaire et organiser IRM ; Horner douloureux <span class=\"nc-red nc-bold\">récent</span> : éliminer dissection en urgence.</p></div>"},{"i":"4c402a144061","n":99,"o":"99-17","u":"Contenu multimédia","t":"A partir d'une vidéo d'interrogatoire, évoquer le diagnostic de migraine, d'algie vasculaire de la face, de névralgie du trijumeau","q":"Décharges de 10 secondes lors du brossage des dents : quelle hypothèse ?","a":"<div class=\"notion-course\"><p>Névralgie du trijumeau. Rechercher territoire, <span class=\"nc-red nc-bold\">zone gâchette</span>, anomalies sensitives et autres nerfs ; IRM et évaluation du retentissement alimentaire.</p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/34b37f85d9418045b56ae76d44b6cb51?pvs=204","reviewedAt":"2026-10-12","note":"Cours Notion restructuré, objectifs complétés et références des collèges/HAS vérifiées. Les couleurs conservent celles de tes passages correspondants."}};
